import { ch, Chapter } from "./_core";

const P10: Chapter[] = [
  ch("b-wph-10", 0, "رساله؛ کتابی که شکست خورد و جهان را ساخت", ["هیوم — که رساله دربارهٔ طبیعت بشر را در بیست‌وشش‌سالگی — ۱۷۳۹ — منتشر کرد — با سکوت روبه‌رو شد؛ و خود بعدها نوشت: «از مطبعه، مرده بیرون آمد». اما همین کتاب — که نویسنده‌اش آن را «بازنویسی» کرد — سرانجام، کانت را بیدار کرد، پوزیتیویسم را ساخت، و فلسفهٔ ذهن و زبان قرن بیستم را شکل داد. رساله — که سه بخش دارد: فهم، تأثرات، و اخلاق — طرحی بلندپروازانه دارد: ساختن «علم انسان» — علمی که چون فیزیک نیوتنی، قوانین ذهن را کشف کند؛ و خواننده باید این طرح را — پیش از جزئیات — در نظر داشته باشد."]),
  ch("b-wph-10", 1, "ادراک‌ها؛ تصورات و تصدیقات", ["هیوم — که می‌خواهد همهٔ شناخت را تحلیل کند — با ساده‌ترین اجزا آغاز می‌کند: «ادراک‌ها» — که دو گونه‌اند: «تصورات» — که با «شدت و حدت» می‌آیند — چون دیدن رنگ یا حس درد؛ و «تصدیقات» — که همان تصورات‌اند اما «کم‌رنگ‌تر» — چون به‌یادآوردن رنگ یا پنداشتن درد. این تمایز — که ساده می‌نماید — بنیاد همهٔ رساله است؛ زیرا هیوم می‌خواهد نشان دهد که «هر تصدیقی» — حتی پیچیده‌ترین مفاهیم فلسفی — از «تصورات» برمی‌خیزد؛ و اگر تصدیقی نتواند «تصور» سازنده‌اش را نشان دهد — چون «جوهر» یا «علت فی‌نفسه» — بی‌معناست. این «معیار هیومی» — که بعداً پوزیتیویست‌ها آن را گرفتند — از شجاع‌ترین ابزارهای فلسفه است."]),
  ch("b-wph-10", 2, "ساده و مرکب؛ تحلیل ذهن", ["هیوم — که می‌خواهد ذهن را چون شیمی‌دان تحلیل کند — میان ادراک‌های «ساده» و «مرکب» تمایز می‌گذارد: ادراک ساده — چون رنگِ سیب — دیگر تحلیل‌ناپذیر است؛ و ادراک مرکب — چون «سیب» — از چند ادراک ساده ساخته شده است. و قانون اساسی: «هر ادراک سادهٔ تصدیقی، تصوری ساده دارد که از آن برمی‌خیزد» — یعنی تصورات، «کپی‌های» تصدیقات‌اند؛ اما ادراک‌های مرکب تصدیقی — چون «شهر طلا» — می‌توانند بدون تصدیقِ واقعی باشند — زیرا ذهن، اجزای کپی‌شده را «ترکیب» می‌کند. این تحلیل — که تخیل را از قید واقعیت می‌رهاند — نشان می‌دهد ذهن — برای هیوم — هم «کپی‌کننده» است و هم «ترکیب‌کننده»؛ و همهٔ فلسفهٔ او، دربارهٔ مرز این دو است."]),
  ch("b-wph-10", 3, "تداعی تصورات؛ جاذبهٔ ذهن", ["هیوم — که می‌خواهد قوانین ذهن را چون قوانین نیوتنی کشف کند — سه اصل «تداعی» می‌شمارد که تصورات را به هم می‌پیوندند: «شباهت» — که تصویر، ما را به اصل می‌برد؛ «مجاورت» — که یاد خانه، ما را به همسایه می‌برد؛ و «علیت» — که یاد زخم، ما را به درد می‌برد. هیوم — این سه اصل را «جاذبهٔ عمومیِ جهان ذهنی» می‌خواند — و می‌گوید: چنان‌که نیوتن، حرکت اجسام را با یک قانون توضیح داد، من می‌خواهم حرکت تصورات را با این سه قانون توضیح دهم. این تشبیه — که رساله را «نیوتنیسمِ ذهن» می‌سازد — کلید فهم هیوم است؛ و خواننده می‌بیند که هیوم — با همهٔ شکاکیتش — به «علم» ایمان داشت؛ اما علمی که موضوعش «انسان» باشد نه «اجرام»."]),
  ch("b-wph-10", 4, "علیت؛ اتصال دائمی", ["قلب رساله — تحلیل «علیت» است: هیوم می‌پرسد «اتصال ضروری» — که می‌گوییم میان علت و معلول هست — از کجا می‌آید؟ و پاسخ می‌دهد: نه از «عقل» — زیرا می‌توانیم بدون تناقض، معلولی را بدون علتش تصور کنیم — و نه از «یک مشاهده» — زیرا یک بار دیدن، «ضرورت» نمی‌سازد؛ بلکه از «اتصال دائمی» — یعنی دیدنِ مکررِ «الف سپس ب» — می‌آید. پس «علیت» — نه چیزی است که «در جهان» ببینیم — که چیزی است که «پس از تکرار» در ذهن ساخته می‌شود؛ و وقتی می‌گوییم «آتش، گرما را لازم می‌آورد» — در حقیقت می‌گوییم: «چون بارها دیده‌ام که پس از آتش، گرما آمده، انتظار دارم که باز بیاید». این تحلیل — که علیت را از جهان به ذهن برد — زلزلهٔ فلسفه بود."]),
  ch("b-wph-10", 5, "عادت؛ راز علیت", ["اگر علیت — از «اتصال دائمی» می‌آید — پس آن نیرویی که این اتصال را به «انتظار» بدل می‌کند چیست؟ پاسخ هیوم — که مشهورترین واژهٔ رساله را ساخت — «عادت» است: «عادت — راهنمای بزرگ زندگی است» — بدون آن، نه از تجربه می‌آموزیم و نه آینده را پیش‌بینی می‌کنیم؛ و علیت — که پایهٔ علم است — خود بر عادت استوار است — نه بر برهان. این نتیجه — که تکان‌دهنده بود — هیوم را به «شکاکیت دربارهٔ استقرا» رساند: ما — چون گذشته را دیده‌ایم — آینده را «انتظار» داریم — اما «دلیل» نداریم؛ زیرا هر دلیلی برای استقرا — خود به استقرا نیاز دارد. این «مسئلهٔ استقرا» — که هیوم طرح کرد — هنوز، پس از سه قرن، باز است؛ و پوپر — که گفت «هیوم، درست می‌گفت» — کل فلسفهٔ علمش را بر همین مسئله ساخت."]),
  ch("b-wph-10", 6, "باور؛ تصدیقِ زنده", ["هیوم — که می‌خواهد بگوید «باور» — که علم از آن ساخته می‌شود — چیست — پاسخ می‌دهد: باور — نه «ایدهٔ تازه» — که «نحوهٔ درکِ ایده» است: «تصدیقی زنده‌تر و قوی‌تر» — که از اتصالش با تصدیق حاضر — به وسیلهٔ عادت — برمی‌خیزد. پس وقتی باور دارم «فردا خورشید طلوع می‌کند» — ایدهٔ طلوع — برایم — «زنده‌تر» است تا وقتی صرفاً «تصورش» می‌کنم؛ و این «زندگی» — که از عادت می‌آید — باور را می‌سازد. این تحلیل — که باور را «حالت روانی» می‌داند نه «مطابقت با واقع» — برای خوانندهٔ معرفت‌شناسی — که باور را «توجیه‌شده و صادق» می‌خواند — تکان‌دهنده است؛ و نشان می‌دهد هیوم — با همهٔ شکاکیتش — می‌خواست باور را — چون پدیده‌ای طبیعی — «توضیح» دهد نه «توجیه»."]),
  ch("b-wph-10", 7, "مسئلهٔ استقرا؛ چرا آینده چون گذشته", ["مسئلهٔ استقرا — که هیوم آن را صریح‌ترین صورت‌بندی کرد — چنین است: همهٔ استدلال‌های ما دربارهٔ «امور واقعیِ ندیده» — چون «فردا خورشید طلوع می‌کند» — بر این فرض‌اند که «طبیعت، یکنواخت است» — آینده چون گذشته است. اما این فرض — خود — چگونه ثابت می‌شود؟ نه با «عقل» — زیرا می‌توانیم بدون تناقض، تغییر طبیعت را تصور کنیم؛ و نه با «تجربه» — زیرا تجربهٔ گذشته — فقط «گذشته» را نشان می‌دهد — و برای رسیدن به آینده — خود به همان فرضِ یکنواختی نیاز دارد — که این «دور» است. پس استقرا — که پایهٔ همهٔ علوم تجربی است — «توجیه» ندارد — فقط «عادت» دارد. هیوم — که این را گفت — نمی‌خواست علم را نابود کند — می‌خواست «بنیادش» را درست بشناسیم: عادت — نه برهان؛ و خواننده می‌بیند که این «تواضع معرفتی» — که هیوم ساخت — از مهم‌ترین میراث‌های اوست."]),
  ch("b-wph-10", 8, "احتمال؛ باورهای ناقص", ["هیوم — که می‌داند همهٔ باورهای ما «یقینی» نیستند — «احتمال» را نیز تحلیل می‌کند: باورهای احتمالی — چون «فردا احتمالاً باران می‌آید» — نیز از «اتصال دائمی» برمی‌خیزند — اما از اتصالی که «ناقص» است — یعنی گاه الف، ب را آورده و گاه نه؛ و ذهن — که میان این تجربه‌های متعارض تقسیم می‌شود — باوری «ضعیف‌تر» می‌سازد. هیوم — که می‌خواهد «علمِ انسان» را کامل کند — حتی «احتمالِ ناشی از شاهدان» را نیز تحلیل می‌کند — و این تحلیل — که بعداً در بحث «معجزات» به کار می‌آید — نشان می‌دهد هیوم — با همهٔ شکاکیتش — به «درجات باور» باور داشت؛ و این درجات — نه از برهان — که از «تجربهٔ گذشته» می‌آیند. خواننده می‌بیند که هیوم — چهار قرن پیش از «نظریهٔ بیزی» — منطق باورهای ناقص را می‌ساخت."]),
  ch("b-wph-10", 9, "هویت شخصی؛ نظریهٔ دسته", ["هیوم — که می‌خواهد «خود» را نیز تحلیل کند — پرسشی می‌پرسد که از مشهورترین صفحات فلسفه است: وقتی «به درون خود می‌نگرم» — چه می‌یابم؟ پاسخ: «هیچ‌گاه — بدون تصدیقی — به خود برنمی‌خورم» — فقط «دسته‌ای از تصورات» می‌یابم — شادی و غم و درد — که می‌آیند و می‌روند؛ و «خودی پایدار» — که پشت این تصورات باشد — نمی‌یابم. پس «هویت شخصی» — که می‌پنداریم داریم — ساختهٔ «تخیل» است: تخیل — که تصوراتِ متوالی را — به وسیلهٔ شباهت و علیت — به هم می‌پیوندد — «وحدتی» می‌سازد که نیست؛ و ما — این وحدتِ ساخته را — «خود» می‌نامیم. این «نظریهٔ دسته» — که بودا — دو هزار سال پیش — گفت و بودیسم آن را «آناتمان» خواند — از تکان‌دهنده‌ترین نتایج رساله است؛ و فلسفهٔ ذهن امروز — از دنیِت تا پارفیت — هنوز با آن کلنجار می‌رود."]),
  ch("b-wph-10", 10, "تئاتر ذهن؛ صحنه‌ای بی صحنه", ["هیوم — که نظریهٔ دسته را می‌گوید — تمثیلی می‌سازد که از مشهورترین تمثیل‌های فلسفه است: ذهن — «تئاتری» است که تصورات — چون بازیگران — در آن می‌آیند و می‌روند؛ اما — و این نکتهٔ ظریف است — «این تصورات — خودِ ذهن‌اند — و هیچ چیز دیگر نیست» — یعنی تئاتر — «صحنه» و «تماشاگر» ندارد؛ فقط «بازیگران» دارد. این تمثیل — که «خود» را از «جایگاه تماشاگر» بیرون می‌کند — با کوگیتوی دکارت — که «منِ تماشاگر» را بنیاد می‌دانست — در ستیز است؛ و خواننده می‌بیند که هیوم — با این تمثیل — «سوژهٔ مدرن» را — که دکارت ساخت — از درون ویران کرد. و جالب آنکه هیوم — خود — اعتراف می‌کند که این نتیجه — در «زندگی عملی» — باورنکردنی است؛ و این «فاصلهٔ نظر و عمل» — که هیوم صادقانه می‌پذیرد — از درس‌های بزرگ رساله است."]),
  ch("b-wph-10", 11, "اجسام خارجی؛ شک دربارهٔ حس", ["هیوم — که ذهن را تحلیل کرد — به «اجسام خارجی» می‌رسد و می‌پرسد: باور ما به «جهان بیرون» — که تصوراتش مستقل از ماست — از کجا می‌آید؟ و پاسخ می‌دهد: نه از «حس» — زیرا حس، فقط «تصورات» می‌دهد نه «اجسام» — و نه از «عقل» — زیرا هیچ برهانی از تصورات به اجسام نداریم؛ بلکه از «تخیل» — که تصوراتِ «پایدار و منسجم» — چون کوه‌ها — را — چون «مستقل» می‌سازد. این تحلیل — که جهان بیرون را «ساختهٔ تخیل» می‌خواند — هیوم را به «شکاکیت دربارهٔ حس» می‌رساند؛ اما — چنان‌که بعداً می‌بینیم — هیوم — این شک را «پایان» نمی‌داند؛ و خواننده می‌بیند که رساله — با همهٔ شکاکیتش — می‌خواهد بفهمد «چرا» ما به جهان باور داریم — حتی اگر این باور، «توجیه‌ناپذیر» باشد."]),
  ch("b-wph-10", 12, "عالم و عامه؛ دو روایت از جهان", ["هیوم — که می‌خواهد بگوید چرا مردم «عادی» به جهان بیرون باور دارند — و فیلسوفان — چرا به شک می‌افتند — دو روایت می‌سازد: روایت «عامه» — که تخیل — به وسیلهٔ «ثبات و انسجام» تصورات — جهان را «مستقل» می‌سازد؛ و روایت «فیلسوفان» — که می‌گویند این جهانِ مستقل، «بازنمایی» است نه «خودِ جهان» — و این روایت — که با «نظریهٔ بازنمایی» شروع می‌شود — به شکاکیت می‌انجامد؛ زیرا اگر فقط «بازنمایی‌ها» را می‌بینیم — چگونه «خودِ جهان» را بشناسیم؟ هیوم — که می‌گوید روایت فیلسوفان — «درست‌تر» اما «باورنکردنی‌تر» است — در این دوراهی می‌ماند؛ و خواننده می‌بیند که رساله — نه «پاسخ» می‌دهد — که «دوراهی» را درست می‌سازد؛ و این — برای هیوم — خود، نوعی «حکمت» است."]),
  ch("b-wph-10", 13, "شکاکیت؛ انواع و حدود", ["هیوم — که می‌خواهد «شکاکیت» خود را روشن کند — میان گونه‌های آن تمایز می‌گذارد: «شکاکیت پیشینی» — که دکارت داشت — و می‌خواهد با شک، به یقین برسد — هیوم آن را «غیرممکن» می‌داند؛ «شکاکیت پسینی» — که از «محدودیت فهم» برمی‌خیزد — و هیوم آن را «لازم» می‌داند؛ و «شکاکیت افراطی» — که پیررونیان داشتند و همه‌چیز — حتی زندگی — را انکار می‌کردند — هیوم آن را «باورنکردنی» می‌داند؛ زیرا «طبیعت» — که از فلسفه قوی‌تر است — ما را به زندگی بازمی‌گرداند. پس شکاکیت هیوم — «میانه» است: نه یقین‌گرایی — و نه انکارگرایی؛ و خواننده می‌بیند که هیوم — با همهٔ شهرتش به شکاکیت — «شکاکِ عمل‌گرا» است؛ و جمله‌اش — «طبیعت، همیشه بر فلسفه پیروز است» — خلاصهٔ موضع اوست."]),
  ch("b-wph-10", 14, "تأثرات؛ تصورات بازتابی", ["بخش دوم رساله — «دربارهٔ تأثرات» — با تحلیلی آغاز می‌شود که تأثرات را در دستگاه هیومی می‌نشاند: تأثرات — چون شادی و غم — «تصورات بازتابی»‌اند — یعنی نه از «اشیاء» — چون تصورات اصلی — که از «تصورات اصلی» برمی‌خیزند؛ و چون «شدت و حدت» دارند — بر «اراده» اثر می‌گذارند. هیوم — که می‌خواهد تأثرات را نیز چون اجسام «قانونمند» بشناسد — آن‌ها را به دو گونه تقسیم می‌کند: «مستقیم» — که بی‌واسطه از خیر و شر برمی‌خیزند — چون شادی و غم؛ و «غیرمستقیم» — که با «ایدهٔ خود یا دیگری» همراه‌اند — چون غرور و تواضع و عشق و نفرت. این تقسیم — که ساده می‌نماید — کلید فهم «اخلاق اجتماعی» هیوم است؛ و خواننده می‌بیند که رساله — که با «فهم» شروع شد — به «دل» می‌رسد؛ زیرا هیوم می‌داند که انسان — پیش از آنکه «بیندیشد» — «می‌خواهد»."]),
  ch("b-wph-10", 15, "تأثرات مستقیم و غیرمستقیم", ["هیوم — که می‌خواهد «مکانیک تأثرات» را بسازد — تأثرات «غیرمستقیم» را با «اصل تداعی مضاعف» توضیح می‌دهد: «غرور» — برای مثال — از دو تداعی برمی‌خیزد: تداعی «ایده‌ها» — که «خانهٔ زیبای من» را به «من» می‌پیوندد — و تداعی «تصورات» — که «زیبایی خانه» — که شادی می‌آورد — این شادی را به «من» — که موضوعش شده — منتقل می‌کند؛ و این شادیِ پیوندخورده با «من» — «غرور» است. هیوم — این مکانیک را — برای تواضع و عشق و نفرت نیز می‌سازد؛ و خواننده می‌بیند که هیوم — چون مهندسی — «مدارهای تأثر» را می‌کشد؛ و این «هندسهٔ دل» — که برای زمانه‌اش شگفت‌انگیز بود — امروز، در روان‌شناسی اجتماعی — که «خودپنداره» و «عزت نفس» را می‌سازد — از نو خوانده می‌شود."]),
  ch("b-wph-10", 16, "غرور و تواضع؛ خود و دارایی‌ها", ["هیوم — که «غرور» را تحلیل می‌کند — می‌گوید: غرور — نه از «خودِ خالی» — که از «دارایی‌های خود» برمی‌خیزد — خانه، زیبایی، فضیلت، حتی خویشاوندان؛ و این دارایی‌ها — چون «به من پیوند دارند» — شادی‌شان — به «من» منتقل می‌شود. اما هیوم — که واقع‌بین است — می‌افزاید: غرور — برای «قابل تحمل بودن» — باید «مبنایی» داشته باشد — غرور بی‌مبنا — که «تکبر» خوانده می‌شود — چون با «واقعیت» نمی‌سازد — به «شکست» می‌انجامد؛ و غرور — باید «پنهان» بماند — زیرا ابراز آن — «تواضعِ دیگران» را می‌رنجاند. این تحلیل‌ها — که از ظریف‌ترین صفحات روان‌شناسی هیوم‌اند — نشان می‌دهند که هیوم — فیلسوفِ شکاک — هم‌زمان «مردم‌شناس» بود؛ و خواننده می‌بیند که رساله — نه فقط «نظریهٔ شناخت» — که «دانشنامهٔ طبیعت انسان» است."]),
  ch("b-wph-10", 17, "عشق و نفرت؛ دیگری", ["هیوم — که «عشق و نفرت» را تحلیل می‌کند — می‌گوید: این دو — چون غرور و تواضع — «تداعی مضاعف» دارند — اما با تفاوت مهم: موضوعشان — «دیگری» است نه «خود»؛ و عشق — که از «فضایل یا زیبایی دیگری» برمی‌خیزد — با «خیرخواهی» همراه است — یعنی میل به خیرِ محبوب؛ و نفرت — که از «رذایل دیگری» برمی‌خیزد — با «بدخواهی» همراه است. هیوم — که می‌خواهد «اجتماع» را از تأثرات بسازد — می‌گوید: عشق — که «همدلی» را می‌سازد — پایهٔ «پیوندهای اجتماعی» است؛ و خواننده می‌بیند که هیوم — با همهٔ شکاکیتش دربارهٔ شناخت — به «پیوند عاطفی» — که انسان‌ها را به هم می‌رساند — ایمان داشت؛ و این ایمان — که بعداً در اخلاقش به «همدلی» می‌انجامد — روح رساله است."]),
  ch("b-wph-10", 18, "اراده؛ آزادی و ضرورت", ["هیوم — که به «اراده» می‌رسد — بحث کهن «آزادی و ضرورت» را بازمی‌سازد؛ اما با وارونه‌نگری: او می‌گوید این بحث — نه دربارهٔ «واقعیت» — که دربارهٔ «تعریف» است؛ زیرا همه — حتی مدافعان «ارادهٔ آزاد» — در عمل می‌پذیرند که «کردار انسان، از motives و شخصیتش پیروی می‌کند» — و این «ضرورت» است؛ و همه — حتی جبرگرایان — می‌پذیرند که «انسان، چنان‌که بخواهد عمل می‌کند» — و این «آزادی» است. پس اختلاف — نه در واقعیت — که در «نام‌گذاری» است؛ و هیوم — با «سازگارگرایی»‌اش — می‌گوید: آزادی — «توانایی عمل بر اساس اراده» — و ضرورت — «پیوند عللی motives و کردار» — نه تنها ناسازگار نیستند — که آزادی — بدون ضرورت — «تصادف» است و «مسئولیت» را نابود می‌کند. این تحلیل — که دنیِت و دیگر سازگارگرایان معاصر آن را ادامه دادند — از ماندگارترین صفحات رساله است."]),
  ch("b-wph-10", 19, "عقل، بردهٔ تأثرات", ["مشهورترین جملهٔ رساله — «عقل — و فقط عقل — بردهٔ تأثرات است و باید باشد» — موضع هیوم دربارهٔ رابطهٔ عقل و اراده را می‌سازد: عقل — که «کشفِ روابط» است — به تنهایی — نمی‌تواند «اراده» را برانگیزد؛ زیرا اراده — از «تأثر» برمی‌خیزد نه از «کشف»؛ و عقل — فقط «وسیله» است — نشان می‌دهد کدام وسیله به کدام هدف می‌رسد — اما «هدف» را — که از تأثر می‌آید — نمی‌سازد. پس جملهٔ مشهور هیوم — «اگر ترجیح دهم انگشت کوچکم نخراشد تا جهان نابود شود — خلاف عقل نیست» — معنایش این است: عقل — «ترجیح‌ها» را داوری نمی‌کند — فقط «وسایل» را. این موضع — که «ضدعقل‌گرایی اخلاقی» خوانده شد — از بحث‌انگیزترین مواضع هیوم است؛ و کانت — که گفت «هیوم مرا بیدار کرد» — کل اخلاقش را بر «ردّ» این جمله ساخت."]),
  ch("b-wph-10", 20, "تأثرات آرام؛ صدای آهستهٔ اخلاق", ["هیوم — که می‌داند جملهٔ «عقل، بردهٔ تأثرات» — ظاهراً اخلاق را نابود می‌کند — تمایزی می‌سازد که نجاتش می‌دهد: تأثرات — دو گونه‌اند: «شدید» — چون خشم و ترس — که پرسروصدا اما کوتاه‌اند؛ و «آرام» — چون «عشق به خیرِ نوع انسان» — که بی‌سروصدا اما پایدارند. و اخلاق — برای هیوم — از «تأثرات آرام» برمی‌خیزد — نه از «عقل خالص» و نه از «تأثرات شدید»؛ و اشتباه فیلسوفان — که اخلاق را «عقلی» خواندند — این بود که «تأثرات آرام» را — چون بی‌سروصدا بودند — «عقل» پنداشتند. این تمایز — که ظریف‌ترین حرکت اخلاق هیومی است — نشان می‌دهد هیوم — نه «ضداخلاق» — که «اخلاق‌شناسِ طبیعی» است؛ و خواننده می‌بیند که رساله — که با شکاکیت شروع شد — با «نجات اخلاق» ادامه می‌یابد."]),
  ch("b-wph-10", 21, "فضیلت و رذیلت؛ تمایز اخلاقی", ["بخش سوم رساله — «دربارهٔ اخلاق» — با پرسشی آغاز می‌شود که کل بخش را می‌سازد: «تمایز میان فضیلت و رذیلت — از کجا می‌آید؟» هیوم — که دو پاسخ را می‌سنجد — «عقل» و «تأثر» — پاسخ اول را رد می‌کند: «رابطهٔ ایده‌ها» — که عقل می‌شناسد — نمی‌تواند «الزام» بسازد؛ و «امور واقعی» — که عقل کشف می‌کند — «بی‌تفاوت»‌اند — و نمی‌توانند «باید» بسازند. پس تمایز اخلاقی — از «تأثر» می‌آید — از «لذت و المی» که از «تماشای کردارها» برمی‌خیزد؛ و «فضیلت» — کرداری است که «تماشایش» — به ما — «لذتِ ویژه» می‌دهد؛ و «رذیلت» — کرداری که «تماشایش» — «المِ ویژه» می‌دهد. این «احساس‌گرایی اخلاقی» — که هیوم را از بنیان‌گذارانش می‌سازد — از بحث‌انگیزترین مواضع رساله است."]),
  ch("b-wph-10", 22, "حس اخلاقی؛ چشمِ دل", ["هیوم — که تمایز اخلاقی را از «تأثر» می‌گیرد — این تأثر را «حس اخلاقی» می‌خواند — حسی که چون چشم — «می‌بیند» — اما «کردارها» را — و چون گوش — «می‌شنود» — اما «ارزش‌ها» را. این حس — که هیوم آن را «مشترک» می‌داند — چون همهٔ انسان‌ها — به طور طبیعی — از «عدالت» لذت می‌برند و از «ظلم» می‌رنجند — پایهٔ «هم‌داوری اخلاقی» است؛ و تفاوت‌های اخلاقی میان فرهنگ‌ها — که ظاهراً این حس را نقض می‌کنند — برای هیوم — «تفاوت در مصادیق» است نه «تفاوت در حس». این «طبیعی‌انگاری اخلاق» — که هیوم ساخت — امروز، با «روان‌شناسی اخلاق» — که نشان می‌دهد قضاوت‌های اخلاقی، پیش از استدلال می‌آیند — تأیید شده است؛ و خواننده می‌بیند که هیوم — چهار قرن پیش — «انقلاب شناختی اخلاق» را پیش‌بینی کرد."]),
  ch("b-wph-10", 23, "عدالت؛ فضیلت مصنوعی", ["مشهورترین تحلیل اخلاقی هیوم — «عدالت، فضیلتی مصنوعی است» — چنین است: فضیلت‌ها — دو گونه‌اند: «طبیعی» — چون مهربانی و سخاوت — که از «تأثر طبیعی» برمی‌خیزند؛ و «مصنوعی» — چون عدالت — که از «قرارداد و مصلحت» برمی‌خیزند. عدالت — برای هیوم — نه از «غریزه» — که از «تدبیر انسان‌ها» ساخته شد: انسان‌ها — که می‌دیدند «مالکیت ناپایدار» به جنگ می‌انجامد — با «قراردادی تدریجی» — که کسی آن را «ننوشت» اما همه آن را «پذیرفتند» — مالکیت را «محترم» شمردند؛ و این احترام — که «مصلحت عمومی» را یاری می‌کند — «عدالت» نام گرفت. این تحلیل — که عدالت را «ساختهٔ اجتماعی» می‌داند — بر حقوق و فلسفهٔ سیاسی اثر عمیق گذاشت؛ و خواننده می‌بیند که هیوم — با همهٔ شکاکیتش — به «نهادهای ساختهٔ انسان» — که بدون «طراح» ساخته شدند — احترامی عمیق داشت."]),
  ch("b-wph-10", 24, "مالکیت؛ سه قانون", ["هیوم — که عدالت را «مصنوعی» خواند — سه «قانون طبیعی مالکیت» را می‌شمارد که «قراردادِ نانوشته» بر آن‌هاست: «ثبات مالکیت» — که هر کس آنچه دارد — نگه دارد؛ «انتقال با رضا» — که مال — فقط با رضایت مالک — جابه‌جا شود؛ و «وفای به عهد» — که وعده‌ها — که آینده را به حال می‌پیوندند — اجرا شوند. این سه قانون — که هیوم آن‌ها را «پیش از دولت» می‌داند — پایهٔ «جامعهٔ مدنی»‌اند؛ و دولت — که بعداً می‌آید — نه «سازندهٔ» این قوانین — که «نگهبان» آن‌هاست. این تحلیل — که دولت را «خدمتگزار عدالت» می‌داند نه «منشأ آن» — از مهم‌ترین میراث‌های هیوم برای فلسفهٔ حقوق است؛ و خوانندهٔ حقوق — که آثار کاتوزیان را خوانده — ریشهٔ بسیاری از اصول حقوقی را در این سه قانون هیومی می‌یابد."]),
  ch("b-wph-10", 25, "قرارداد؛ نه وعده", ["هیوم — که می‌خواهد بگوید «قرارداد اجتماعی» — که هابز و لاک ساختند — چگونه ممکن شد — نکته‌ای ظریف می‌گوید: قرارداد — «وعده» نیست؛ زیرا وعده — که «الزام» می‌سازد — خود «ساختهٔ قرارداد» است — پس نمی‌تواند «پایهٔ» آن باشد. قرارداد — برای هیوم — «هم‌سویی منافع» است: من — چون می‌بینم که «رعایت مالکیت تو» به «سود من» است — و تو نیز چنین — با «انتظار متقابل» — به توافق می‌رسیم — بی‌آنکه «وعده‌ای» داده باشیم؛ و این توافق — که تدریجی است و «نانوشته» — «قرارداد» است. این تحلیل — که قرارداد را از «توافق صریح» به «هم‌سویی ضمنی» می‌برد — از شگفت‌انگیزترین حرکات رساله است؛ و خواننده می‌بیند که هیوم — با این حرکت — نظریهٔ قرارداد اجتماعی را — نه نابود — که «طبیعی» کرد."]),
  ch("b-wph-10", 26, "دولت؛ خاستگاه و اطاعت", ["هیوم — که می‌خواهد «دولت» را نیز از «طبیعت انسان» بسازد — می‌گوید: دولت — نه از «قرارداد نخستین» — که از «تجربهٔ ناکارآمدی عدالتِ بدون دولت» برمی‌خیزد: انسان‌ها — که دیدند «عدالت» — بدون «قدرتی که اجرا کند» — به «تجاوز» می‌انجامد — «حاکمان» را ساختند تا «قوانین عدالت» را اجرا کنند؛ و اطاعت از حاکمان — نه از «وعدهٔ نخستین» — که از «مصلحت» برمی‌خیزد — یعنی تا وقتی حاکم — «عدالت» را اجرا می‌کند — اطاعت — «مفید» است. اما هیوم — که واقع‌بین است — حدی نیز می‌گذارد: اگر حاکم — «ظالم مطلق» شود — که اطاعتش «مضر» است — «حق اطاعت» پایان می‌یابد. این تحلیل — که اطاعت را «مشروط به کارکرد» می‌داند — از مهم‌ترین میراث‌های هیوم برای فلسفهٔ سیاسی است."]),
  ch("b-wph-10", 27, "باید و هست؛ پاراگراف مشهور", ["در میانهٔ بخش اخلاق — هیوم پاراگرافی می‌نویسد که از مشهورترین صفحات فلسفه است: «در همهٔ دستگاه‌های اخلاقی که تاکنون دیده‌ام — نویسنگان از «هست» — که توصیف است — به «باید» — که الزام است — می‌پرند — بی‌آنکه بگویند این «پرش» چگونه ممکن است». هیوم — که این «پرش» را «غیرموجه» می‌خواند — می‌گوید: «باید» — از «هست» برنمی‌خیزد — مگر با «تأثری» که این دو را بپیوندد. این «شکاف هیومی» — که بعداً «گیوتین هیومی» خوانده شد — پایهٔ «فرااخلاق» معاصر است؛ و پوزیتیویست‌ها — که «تفکیک واقعیت و ارزش» را ساختند — از همین پاراگراف برخاستند. خواننده می‌بیند که یک پاراگراف — که هیوم آن را «تقریباً بی‌اهمیت» خواند — سرنوشت اخلاق را در سه قرن بعد ساخت."]),
  ch("b-wph-10", 28, "چنگال هیوم؛ دو راه شناخت", ["هیوم — در «پرسش دربارهٔ فهم بشری» — بازنویسی رساله — «چنگال» مشهورش را می‌سازد: همهٔ «موضوعات عقل» — دو گونه‌اند: «روابط ایده‌ها» — چون ریاضیات — که «یقینی»‌اند اما «دربارهٔ جهان» نیستند؛ و «امور واقعی» — چون فیزیک — که «دربارهٔ جهان»‌اند اما «احتمالی»‌اند. و هر کتابی — که نه «روابط ایده‌ها» دارد و نه «امور واقعی» — باید «به آتش سپرده شود — زیرا جز مغالطه و فریب نیست». این «چنگال» — که متافیزیک را — که نه ریاضی است و نه تجربه — از دو راه بیرون می‌کند — از شجاع‌ترین معیارهای معرفت است؛ و کانت — که گفت «هیوم مرا از خواب جزمی بیدار کرد» — کل نقد عقل محض را برای «ردّ» این چنگال نوشت؛ و خواننده می‌بیند که تاریخ فلسفه — زنجیرهٔ پاسخ‌ها به هیوم است."]),
  ch("b-wph-10", 29, "ایده‌های انتزاعی؛ اسم‌گرایی", ["هیوم — که می‌خواهد «ایده‌های انتزاعی» — چون «انسانیت» و «مثلث بودن» — را نیز تحلیل کند — اسم‌گرایی را می‌سازد: «ایدهٔ انتزاعی» — وجود جدا ندارد؛ آنچه داریم — «ایده‌های جزئی»‌اند — چون این مثلث — که به وسیلهٔ «عادت» و «نام» — به «همهٔ مثلث‌ها» اطلاق می‌شوند. پس «مثلث بودن» — نه «ایده‌ای در ذهن» — که «عادتِ اطلاق نام» است؛ و هیوم — که برکلی را در این تحلیل می‌ستاید — می‌گوید: ما — چون «شباهت» میان جزئیات را می‌بینیم — «نام مشترک» می‌سازیم — و این نام — چون به همه اطلاق می‌شود — «انتزاعی» می‌نماید. این تحلیل — که «کلیات» را به «عادت زبانی» فرومی‌کاهد — بر فلسفهٔ زبان قرن بیستم — از ویتگنشتاین تا کویین — اثر گذاشت؛ و خواننده می‌بیند که هیوم — با این تحلیل — راه را برای «نقد مفاهیم متافیزیکی» گشود."]),
  ch("b-wph-10", 30, "معجزات؛ نقد شهادت", ["هیوم — در «پرسش دربارهٔ فهم بشری» — «معجزات» را نیز می‌سنجد؛ و نقدش — که از مشهورترین نقدهای فلسفی است — چنین است: معجزه — «نقض قانون طبیعی» است؛ و باور ما به قوانین طبیعی — از «تجربهٔ یکنواخت» برمی‌خیزد — که «قوی‌ترین» تجربه است؛ پس باور به معجزه — برای موجه بودن — نیازمند «شهادتی» است که «قوی‌تر از تجربهٔ یکنواخت» باشد — و چنین شهادتی — در تاریخ — نیست؛ زیرا «شاهدان» — همیشه — یا «کافی نیستند» یا «متمایل به فریب‌اند» یا «علاقه‌مند به شگفتی». نتیجهٔ هیوم: «معجزه — هرگز — با شهادت ثابت نمی‌شود» — و خواننده می‌بیند که هیوم — که معجزات را از «دین» جدا می‌کند — نه «دین» را هدف گرفته — که «استدلال به معجزه» را؛ و این نقد — که هنوز، پس از سه قرن، در فلسفهٔ دین زنده است — از ماندگارترین میراث‌های هیوم است."]),
  ch("b-wph-10", 31, "تاریخ طبیعی دین؛ خاستگاه دین", ["هیوم — در «تاریخ طبیعی دین» — پرسشی می‌پرسد که برای زمانه‌اش نو بود: دین — «چگونه» زاده شد؟ و پاسخ می‌دهد: نه از «تأمل در نظم جهان» — که از «ترس و امید» — انسان‌های نخستین — که از «علل پنهان» رویدادها — چون طوفان و بیماری — می‌ترسیدند — این علل را «ارواح» پنداشتند؛ و این «ارواح‌باوری» — که چندخدایی بود — بعداً — به دلایل سیاسی و فلسفی — به «یکتاپرستی» رسید. این «طبیعی‌انگاری دین» — که دین را «پدیدهٔ انسانی» می‌خواند — از بنیان‌های «دین‌شناسی» معاصر است؛ و خواننده می‌بیند که هیوم — با این کتاب — راهی گشود که دورکیم و فروید و الیاده — هر یک به راه خود — ادامه دادند."]),
  ch("b-wph-10", 32, "گفت‌وگوهای دین طبیعی؛ نقد برهان نظم", ["هیوم — در «گفت‌وگوهای دین طبیعی» — که پس از مرگش منتشر شد — «برهان نظم» — که از طراحی جهان به طراح می‌رسد — را با سه شخصیت می‌سنجد: «دمیا» — که برهان را می‌گوید؛ «فیلون» — که آن را می‌کوبد؛ و «کلئانتس» — که میانه‌روی می‌کند. نقد فیلون — که بسیاری آن را موضع هیوم می‌دانند — چند وجه دارد: جهان — بیش از «ماشین» — به «حیوان» یا «گیاه» می‌ماند — پس چرا «طراح ماشینی»؟؛ جهان — ممکن است «آزمایشِ ناتمامِ خدایی جوان» باشد؛ و حتی اگر «طراحی» باشد — «یک طراح» لازم نیست — شاید «چند طراح» بوده باشند. این گفت‌وگو — که از شاهکارهای ادبیات فلسفی است — نشان می‌دهد هیوم — حتی در بحث خدا — «گفت‌وگو» را بر «جزم» ترجیح می‌داد؛ و خواننده می‌بیند که هیوم — که «ملحد» خوانده می‌شد — خود را «شکاک» می‌خواند؛ و این فاصله — برای فهم هیوم — حیاتی است."]),
  ch("b-wph-10", 33, "پرسش‌ها؛ بازنویسی رساله", ["هیوم — که رساله را «بازنویسی» کرد — دو «پرسش» ساخت: «پرسشی دربارهٔ فهم بشری» — ۱۷۴۸ — و «پرسشی دربارهٔ اصول اخلاق» — ۱۷۵۱؛ و خواننده باید بداند که این بازنویسی — نه «تکرار» — که «تعدیل» است: هیوم — در پرسش‌ها — «شکاکیت» رساله را «نرم‌تر» کرد — و «بحث‌های متافیزیکی» — چون نظریهٔ دسته — را «کم‌رنگ‌تر» — و در مقابل، «تحلیل‌های اخلاقی و دینی» را «پررنگ‌تر». این تعدیل — که هیوم را از «شکاک افراطی» به «فیلسوف عمل‌گرا» بدل کرد — موضوع بحث است: آیا هیوم — «تغییر موضع» داد یا فقط «تغییر بیان»؟ خوانندهٔ جدی — که می‌خواهد هیوم را کامل بفهمد — باید هم رساله — که «جوان و جسور» است — و هم پرسش‌ها — که «پخته و محتاط» — را بخواند؛ و این دوگانه — خود، درس است."]),
  ch("b-wph-10", 34, "خلاصه؛ رساله در یک نگاه", ["هیوم — که می‌خواست رساله را «خواندنی» کند — «خلاصه‌ای» از آن نوشت — که امروز می‌دانیم کار خود اوست؛ و این خلاصه — که رساله را در چند صفحه می‌چکاند — برای خوانندهٔ امروز نیز بهترین «نقشه» است: رساله — می‌گوید هیوم — می‌خواهد «علم انسان» را بسازد — با همان روشی که نیوتن «علم طبیعت» را ساخت؛ و این علم — با «تحلیل ادراک‌ها» شروع می‌شود، به «علیت و استقرا» می‌رسد، «هویت شخصی» را می‌سازد، «تأثرات» را قانونمند می‌کند، و با «اخلاقِ مبتنی بر همدلی» تمام می‌شود. خواننده — که پیش از خواندن رساله — این خلاصه را بخواند — «نقشهٔ راه» دارد؛ و این — برای کتابی هزار صفحه‌ای — نعمتی است که خود نویسنده فراهم کرده است."]),
  ch("b-wph-10", 35, "بیداری کانت؛ هیوم و نقد", ["کانت — که در «مقدمهٔ گزارش‌های متافیزیکی» — ۱۷۶۳ — و بعداً در «مقدمهٔ پیشگفتار» — اعتراف کرد: «هیوم — نخستین کسی بود که مرا از خواب جزمی بیدار کرد» — از هیوم «مسئلهٔ علیت» را گرفت — اما پاسخ دیگری داد: هیوم — که علیت را «عادت» می‌دانست — نتوانست «علم» را نجات دهد؛ و کانت — که می‌خواست علم را نجات دهد — علیت را «مقولهٔ پیشینی فهم» خواند — که بدون آن، «تجربه» ممکن نیست. پس کانت — پرسش هیوم را «پذیرفت» — اما پاسخش را «رد» کرد؛ و این «پذیرش پرسش و ردّ پاسخ» — که کل نقد عقل محض را ساخت — نشان می‌دهد هیوم — حتی برای مخالفانش — «آغاز» است. خواننده — که رساله را خوانده و به نقد عقل محض می‌رود — باید این پل را ببیند؛ زیرا بدون هیوم — کانت — «بیدار» نمی‌شد."]),
  ch("b-wph-10", 36, "روشنگری اسکاتلندی؛ هیوم و اسمیت", ["هیوم — که در «روشنگری اسکاتلندی» — با آدام اسمیت و فرگوسن و رید — بود — نه تنها فیلسوف — که «مرد اجتماعی» بود: اسمیت — که «ثروت ملل» را نوشت — «دوست صمیمی» هیوم بود — و کتابش را با «تاریخ طبیعی دین» هیوم — که می‌خواست «دین را طبیعی» کند — «هم‌سخن» ساخت؛ و «دست نامرئی» اسمیت — که می‌گوید «منافع شخصی — به خیر عمومی می‌انجامد» — وارث «عدالت مصنوعی» هیوم است — که می‌گفت «مصلحت شخصی — به قرارداد عمومی می‌انجامد». این پیوند — که فلسفه و اقتصاد را یکی می‌کند — از مهم‌ترین میراث‌های روشنگری اسکاتلندی است؛ و خوانندهٔ مکتب‌خانه — که ثروت ملل را نیز می‌خواند — می‌بیند که این دو کتاب — «دو روی یک سکه»‌اند؛ و خواندن یکی بدون دیگری — نیمه است."]),
  ch("b-wph-10", 37, "پوزیتیویسم منطقی؛ وارثان ویتنی", ["پوزیتیویست‌های منطقی — حلقهٔ وین — هیوم را «پدر» خود خواندند: «چنگال هیوم» — که متافیزیک را به آتش می‌سپارد — پیش‌درآمد «اصل تأییدپذیری» آنان بود؛ و «تحلیل ادراک‌ها» — پیش‌درآمد «تحلیل منطقی زبان». اما هیوم — اگر زنده بود — شاید این «وارثان» را نمی‌پذیرفت؛ زیرا پوزیتیویست‌ها — «علم» را «یقین» می‌خواستند — و هیوم — که شکاک بود — علم را «احتمال» می‌دانست؛ و پوزیتیویست‌ها — «احساس‌گرایی» را به «زبان» بردند — و هیوم — آن را در «طبیعت انسان» نگه داشت. این «وارثیِ ناقص» — که برای بسیاری از متفکران رخ می‌دهد — درس است؛ و خواننده می‌بیند که هر مکتبی — از بزرگان — «آنچه می‌خواهد» برمی‌دارد — و وظیفهٔ خوانندهٔ جدی — «بازگرداندن تمامِ هیوم» است."]),
  ch("b-wph-10", 38, "پوپر؛ مسئلهٔ استقرا زنده است", ["کارل پوپر — که گفت «هیوم — دربارهٔ استقرا — درست می‌گفت» — مسئلهٔ هیوم را جدی‌ترین مسئلهٔ فلسفهٔ علم خواند؛ اما راه‌حلی پیشنهاد کرد که هیوم نداشت: علم — نه از «استقرا» — که از «حدس و ابطال» می‌آید — یعنی دانشمندان — «نظریه» را حدس می‌زنند — و سپس — با «تلاش برای ابطالش» — آن را می‌سنجند؛ و نظریه‌ای که «ابطال‌ناپذیر» باشد — چون «علمی نیست». این راه‌حل — که پوپر را از بزرگان فلسفهٔ علم ساخت — اما خود نیز نقد شد — چون کوهن و لاکاتوش نشان دادند که دانشمندان — در عمل — نظریه‌ها را به این سادگی «ابطال» نمی‌کنند. اما نکتهٔ مهم — برای خواننده — این است: مسئلهٔ هیوم — که سه قرن پیش طرح شد — هنوز «موتور» فلسفهٔ علم است؛ و این — معنای «کلاسیک بودن» است."]),
  ch("b-wph-10", 39, "کویین؛ معرفت‌شناسی طبیعی‌شده", ["کویین — که در «دو جزم تجربه‌گرایی» — پوزیتیویسم را کوبید — راهی رفت که از هیوم برمی‌خید: «معرفت‌شناسی طبیعی‌شده» — یعنی معرفت‌شناسی — نه «دادگاهی فراتر از علم» — که «بخشی از علم» است — روان‌شناسی‌ای که می‌پرسد «انسان — چگونه — از تحریکات حسی — به نظریه‌های علمی می‌رسد؟». این حرکت — که کویین آن را از هیوم گرفت — می‌گفت: هیوم — که می‌خواست «علم انسان» را بسازد — درست می‌رفت — اما ابزارش — «تحلیل مفاهیم» — کم بود؛ و امروز — با «روان‌شناسی و علوم اعصاب» — می‌توانیم «علم انسان» هیومی را — با ابزارهای بهتر — ادامه دهیم. این خوانش — که هیوم را «پدر معرفت‌شناسی طبیعی» می‌داند — از زنده‌ترین خوانش‌های معاصر است؛ و خواننده می‌بیند که رساله — با سه قرن فاصله — هنوز «برنامهٔ پژوهشی» است."]),
  ch("b-wph-10", 40, "هیوم در فرااخلاق؛ بیان‌گرایی", ["هیوم — که تمایز اخلاقی را از «تأثر» گرفت — برای «فرااخلاق» معاصر — که می‌پرسد «جملات اخلاقی چه می‌کنند؟» — از مهم‌ترین منابع است: بیان‌گرایان — چون آیر و استیونسون — گفتند: جملات اخلاقی — چون «دزدی بد است» — «توصیف» نمی‌کنند — «ابراز تأثر» می‌کنند — و این — دقیقاً — همان است که هیوم گفت: «فضیلت — کرداری است که تماشایش — لذتِ ویژه می‌دهد» — یعنی جملهٔ اخلاقی — «گزارش تأثر» است. اما بیان‌گرایان — از هیوم فاصله گرفتند — زیرا هیوم — تأثر اخلاقی را «طبیعی و مشترک» می‌دانست — و آنان — آن را «شخصی» خواندند؛ و خواننده می‌بیند که حتی «وارثی» — می‌تواند «خیانت» باشد — و وظیفهٔ خوانندهٔ جدی — «بازگشت به متن» است."]),
  ch("b-wph-10", 41, "هیوم و علوم شناختی", ["هیوم — که می‌خواست «علم انسان» را چون فیزیک بسازد — امروز، با «علوم شناختی» — از نو خوانده می‌شود: «تداعی تصورات» — که هیوم آن را «جاذبهٔ ذهن» خواند — در «شبکه‌های عصبی» — که «اتصالات» را تقویت می‌کنند — بازسازی شده؛ «عادت» — که پایهٔ علیت هیومی است — در «یادگیری آماری» — که مغز را «پیش‌بینی‌کننده» می‌داند — زنده است؛ و «تأثرات آرام» — که هیوم آن‌ها را پایهٔ اخلاق می‌دانست — در «روان‌شناسی اخلاق» — که می‌گوید قضاوت اخلاقی — پیش از استدلال می‌آید — تأیید شده است. این «بازگشت هیوم» — که در علوم شناختی جریان دارد — نشان می‌دهد که «علم انسان» هیومی — نه «رویا» — که «برنامه» بود؛ و خواننده می‌بیند که هیوم — چهار قرن پیش — «نقشهٔ راهی» کشید که امروز — با ابزارهای نو — طی می‌شود."]),
  ch("b-wph-10", 42, "هیوم؛ مورخ", ["هیوم — که امروز او را «فیلسوف» می‌شناسیم — در زمانهٔ خود — بیش از همه — «مورخ» بود: «تاریخ انگلستان» او — که شش جلد است — در سدهٔ هجدهم — از پرفروش‌ترین کتاب‌ها بود؛ و هیوم — که «تاریخ» را «آزمایشگاه علم انسان» می‌دانست — در آن — «طبیعت انسان» را — در «بستر زمان» — می‌آزمود. این «تاریخ‌نگاری هیومی» — که از روایت «نخبگان» به روایت «تمدن» — اقتصاد و حقوق و فرهنگ — گذر کرد — بر تاریخ‌نگاری بعدی اثر گذاشت؛ و خواننده می‌بیند که هیوم — با همهٔ شکاکیتش دربارهٔ «استقرا» — به «درس‌های تاریخ» — که از «تجربهٔ ملل» برمی‌خیزد — باور داشت؛ و این — برای خوانندهٔ مکتب‌خانه — که تاریخ می‌خواند — درس است: تاریخ — نه «قصه» — که «آزمایشگاه» است."]),
  ch("b-wph-10", 43, "جستارهای هیوم؛ اقتصاد و سیاست", ["هیوم — که «جستارهای اخلاقی، سیاسی و ادبی» را نوشت — در آن — بحث‌هایی دارد که امروز نیز زنده‌اند: در «دربارهٔ بازرگانی» — می‌گوید «ثروت ملل» — در «طلا و نقره» نیست — در «کار و صنعت» است — و این — پیش‌درآمد اسمیت است؛ در «دربارهٔ بهره» — می‌گوید «بهرهٔ پایین» — نشانهٔ «ثروت» نیست — نشانهٔ «تجارت گسترده» است؛ و در «ایدهٔ حکومت کامل» — می‌گوید «بهترین حکومت» — نه «دموکراسی مطلق» و نه «سلطنت مطلق» — «حکومت مخلوط» است — که «قانون» در آن — بر «افراد» برتری دارد. این جستارها — که هیوم را «اقتصاددان» نیز می‌سازند — نشان می‌دهند که او — نه فقط «فیلسوفِ نظر» — که «اندیشمندِ عمل» بود؛ و خوانندهٔ مکتب‌خانه — که اقتصاد سیاسی می‌خواند — باید این جستارها را — در کنار اسمیت و ریکاردو — بخواند."]),
  ch("b-wph-10", 44, "زندگی هیوم؛ قدیس ادینبورگ", ["هیوم — که در ۱۷۱۱ در ادینبورگ به دنیا آمد — زندگی‌ای داشت که خود می‌گفت «داستانِ یک مردِ اهل قلم» است: کتاب‌هایش — که ابتدا بی‌فروش بودند — کم‌کم خوانده شدند؛ او — که «منصب دانشگاهی» نیافت — «کتابدار» شد و «تاریخ» نوشت؛ و در ۱۷۷۶ — که مرد — آدام اسمیت — در نامه‌ای مشهور — او را «به انسانیت کامل‌ترین» خواند. این زندگی — که «آرامش» در دل «شکاکیت» بود — خود، پاسخ هیوم به منتقدانش است: کسانی که می‌گفتند «شکاکیت — به بی‌اخلاقی می‌انجامد» — با «زندگی هیوم» روبه‌رو شدند — که نمونهٔ «اخلاقِ بی‌جزم» بود. و خواننده می‌بیند که هیوم — با زندگی‌اش — آنچه را که با رساله‌اش گفت — «تأیید» کرد: انسان — می‌تواند «شکاک» باشد — و «نیک»؛ و این — شاید مهم‌ترین درس هیوم باشد."]),
  ch("b-wph-10", 45, "هیوم و دین؛ موضع واقعی", ["موضع هیوم دربارهٔ دین — که «ملحد» خوانده شد — در حقیقت — «شکاکانه» است: او — در «تاریخ طبیعی دین» — «خاستگاه» دین را طبیعی می‌خواند؛ در «گفت‌وگوها» — «برهان‌های» دین را می‌سنجد و «ناتمام» می‌یابد؛ و در «معجزات» — «شهادت به معجزه» را «بی‌اعتبار» می‌داند. اما هیوم — «خدای فیلسوفان» — که «علت نخست» است — را یکسره رد نمی‌کند — می‌گوید: «ما — از این موضوع — نمی‌دانیم» — و این — «ندانم‌گرایی» است نه «الحاد». خواننده باید این فاصله را — که هیوم خود بر آن اصرار داشت — جدی بگیرد؛ زیرا «شکاک» — که می‌گوید «نمی‌دانم» — با «ملحد» — که می‌گوید «نیست» — فرق دارد؛ و هیوم — که از «جزم» — در هر دو سو — می‌گریخت — «شکاک» بود."]),
  ch("b-wph-10", 46, "هیوم و زیبایی‌شناسی؛ معیار ذوق", ["هیوم — در «دربارهٔ معیار ذوق» — پرسشی را طرح می‌کند که هنوز زنده است: اگر «زیبایی — در چشم بیننده است» — پس چرا دربارهٔ «شکسپیر» — تقریباً همه توافق دارند — و دربارهٔ «شاعری ضعیف» — تقریباً همه؟ پاسخ هیوم — «معیارِ مرکب» است: زیبایی — نه «در شیء» است — که «در تأثرِ بیننده»؛ اما این تأثر — در «بینندگانِ خوب» — که «حس دقیق» و «تمرین فراوان» و «تعصبِ کم» دارند — «یکنواخت» است؛ و این «یکنواختیِ بینندگانِ خوب» — «معیار ذوق» است. این تحلیل — که زیبایی‌شناسی را «طبیعی» می‌کند — بدون آن را «نسبی مطلق» کند — از ظریف‌ترین حرکات هیوم است؛ و خوانندهٔ هنر — که شناخت هنر پاکباز را خوانده — می‌بیند که پرسش «معیار زیبایی» — از هیوم تا امروز — باز است."]),
  ch("b-wph-10", 47, "هیوم و فمینیسم؛ زنان", ["هیوم — که در جستار «دربارهٔ مهر و ازدواج» — دربارهٔ زنان نیز نوشت — موضعی دوچهره دارد: از یک سو — می‌گوید زنان — چون مردان — «عقل و تأثر» دارند — و «حقِ انتخاب همسر» — که او از آن دفاع می‌کند — برای آنان نیز هست؛ و از سوی دیگر — سخنانی دارد — چون «زنان — بیش از مردان — به زیبایی‌اند» — که امروز — «جنسیت‌زده» خوانده می‌شود. خوانندهٔ جدی — باید این دوچهرگی را — چون دوچهرگی‌های ارسطو و مونتنی — صادقانه ببیند؛ و فمینیست‌های هیومی — چون آنِت بایر — کوشیده‌اند نشان دهند که «اخلاقِ همدلی» هیوم — اگر جدی گرفته شود — «علیه» جنسیت‌زدایی خود اوست. این «نقد از درون» — که سنت را با ابزارهای خودش می‌سنجد — از روش‌های ماندگار فلسفه است."]),
  ch("b-wph-10", 48, "چگونه رساله را بخوانیم", ["برای خواندن رساله — که هزار صفحه است و نثری قرن هجدهمی دارد — این روش پیشنهاد می‌شود: نخست — «خلاصه» هیوم را بخوانید — که نقشهٔ راه است؛ دوم — کتاب اول — «دربارهٔ فهم» — را بخش‌به‌بخش بخوانید و «دفترچهٔ تعریف‌ها» بسازید — ادراک، تداعی، عادت؛ سوم — بخش «علیت» — که قلب کتاب است — را دو بار بخوانید؛ چهارم — کتاب دوم — «تأثرات» — را با «زندگی خود» بخوانید — و ببینید کدام تأثرات‌تان «مستقیم»‌اند و کدام «غیرمستقیم»؛ و پنجم — کتاب سوم — «اخلاق» — را با «پرسش تطبیقی» بخوانید: «عدالت مصنوعی» هیوم — با «حسن و قبح عقلی» کلام شیعه — چه نسبتی دارد؟ با این روش — رساله — از «کتابی دشوار» — به «گفت‌وگویی زنده» بدل می‌شود."]),
  ch("b-wph-10", 49, "جمع‌بندی؛ هیوم و ما", ["پنجاه فصل این سیر — از ادراک‌ها تا معیار ذوق — رساله را پیمود؛ و اکنون خواننده می‌داند که این کتاب — با همهٔ شکاکیتش — «کتاب طبیعت انسان» است: هیوم — که می‌خواست بفهمد «انسان — چگونه می‌فهمد، می‌خواهد، و داوری می‌کند» — با «شکاکیت» — «تواضع» ساخت؛ با «عادت» — «علم» را نجات داد؛ و با «همدلی» — «اخلاق» را — بی‌جزم — نگه داشت. میراث هیوم — که کانت و پوپر و کویین و علوم شناختی — هر یک — از او برخاستند — نشان می‌دهد که «شکاکِ بزرگ» — در حقیقت — «سازندهٔ بزرگ» بود؛ و خواننده‌ای که رساله را خوانده — دیگر نمی‌تواند «یقین‌های ساده» را بپذیرد — بی‌آنکه «هزینه‌شان» را بداند؛ و این — آغاز خرد هیومی است.", ["پروژه‌های پیشنهادی", "برای مقطع پژوهشی، چند پروژه پیشنهاد می‌شود: «علیت هیومی و مقولهٔ کانتی؛ دو پاسخ به یک مسئله»؛ «عدالت مصنوعی هیوم و قواعد عمومی قراردادها»؛ «تداعی تصورات و شبکه‌های عصبی»؛ و «همدلی هیومی و همدلی در اخلاق اسلامی». هر یک از این پروژه‌ها — اگر با خوانش مستقیم رساله و روش تطبیقی انجام شود — می‌تواند خواننده را از خوانندهٔ هیوم — به گفت‌وگوکننده با هیوم برساند؛ و این — همان مرتبه‌ای است که مکتب‌خانه — در همهٔ سیرهایش — خواننده را بدان می‌خواند."]]),
];

const P11: Chapter[] = [
  ch("b-wph-11", 0, "قرارداد اجتماعی؛ جملهٔ آغازین", ["قرارداد اجتماعی — که روسو در ۱۷۶۲ نوشت — با جمله‌ای آغاز می‌شود که از مشهورترین جملات تاریخ سیاست است: «انسان آزاد زاده می‌شود — و همه‌جا در زنجیر است». این جمله — که هم «تشخیص» است و هم «اتهام» — کل کتاب را می‌سازد: انسان — به «طبیعت» آزاد است؛ اما «جامعه‌ها» — که باید آزادی را پاس بدارند — آن را می‌گیرند؛ و پرسش روسو این است: آیا می‌توان جامعه‌ای ساخت که در آن — انسان — «چنان‌که آزاد زاده شد» — آزاد بماند؟ قرارداد اجتماعی — پاسخ روسو به این پرسش است؛ و خواننده باید این پرسش را — پیش از هر صفحه — در نظر داشته باشد؛ زیرا همهٔ کتاب — برای پاسخ به آن است."]),
  ch("b-wph-11", 1, "گفتارها؛ راه قرارداد", ["قرارداد اجتماعی — را نمی‌توان بی‌دو «گفتار» روسو فهمید: «گفتار دربارهٔ علوم و هنرها» — ۱۷۵۰ — که می‌گوید «پیشرفت علوم و هنرها — اخلاق را فاسد کرده» — و «گفتار دربارهٔ نابرابری» — ۱۷۵۵ — که می‌گوید «نابرابری — نه طبیعی — که اجتماعی است». این دو گفتار — که روسو را «دشمن تمدن» خواندند — در حقیقت — «تشخیص»‌اند: تمدن — چنان‌که هست — «انسان را فاسد کرده»؛ و قرارداد اجتماعی — «نسخه» است: جامعه‌ای که «انسان را فاسد نکند». خواننده — که این سیر را ببیند — می‌فهمد که روسو — نه «ضدجامعه» — که «ضدجامعهٔ فاسد» است؛ و نسخه‌اش — قرارداد — برای «جامعهٔ سالم» است."]),
  ch("b-wph-11", 2, "وضع طبیعی؛ انسان طبیعی", ["روسو — که در گفتار دوم — «وضع طبیعی» را می‌سازد — تصویری متفاوت از هابز می‌دهد: انسان طبیعی — برای روسو — نه «گرگِ انسان» — که «موجودی تنها و آرام» است — که نیازهایش «ساده»‌اند — غذا، خواب، جفت — و «عقلش» — چون نیاز پیچیده‌ای ندارد — «خفته» است. این انسان — که روسو او را «وحشی نجیب» خوانده‌اند — نه «خیر» است و نه «شر» — «پیشاخیر و شر» است؛ و «خوددوستی» — amour de soi — که دارد — «طبیعی» است — یعنی برای «بقا» است — نه برای «برتری». این تصویر — که روسو آن را «فرض» می‌خواند نه «تاریخ» — برای او — «معیار» است: هر جامعه‌ای — که انسان را از این «آرامش طبیعی» دورتر کند — باید «توجیه» شود؛ و قرارداد — این توجیه است."]),
  ch("b-wph-11", 3, "خوددوستی و خودپسندی؛ دو عشق نفس", ["روسو — برای توضیح «فساد تمدن» — تمایزی می‌سازد که از ماندگارترین مفاهیم اوست: «خوددوستی» — amour de soi — عشق طبیعی به خود — که «بقا» را می‌جوید و «با دیگران» نمی‌سنجد؛ و «خودپسندی» — amour-propre — عشق اجتماعی به خود — که «برتری بر دیگران» را می‌جوید و «با دیگران» می‌سنجد. انسان طبیعی — فقط خوددوستی دارد؛ اما انسان اجتماعی — با «مقایسه» — خودپسندی پیدا می‌کند — و این — ریشهٔ «حسد، غرور، و رقابت» است. پس فساد تمدن — برای روسو — نه در «علوم و هنرها» — که در «خودپسندی» است — که انسان را «بندهٔ نظر دیگران» می‌کند؛ و خواننده می‌بیند که این تمایز — که چهار قرن بعد — در روان‌شناسی — «عزت نفس درونی و بیرونی» خوانده شد — از شگفت‌انگیزترین یافته‌های روسوست."]),
  ch("b-wph-11", 4, "کمال‌پذیری؛ چرا انسان تغییر می‌کند", ["روسو — که می‌خواهد بگوید چرا انسان — از «وضع طبیعی» به «تمدن» رسید — «کمال‌پذیری» را می‌سازد: انسان — بر خلاف حیوانات — که «طبیعتشان» کارشان را تعیین می‌کند — «قابلیتِ تغییر» دارد — و این قابلیت — که «همهٔ توانایی‌هایش را در طول زمان می‌گشاید» — هم «منشأ پیشرفت» است و هم «منشأ فساد». کمال‌پذیری — که با «تصادف‌ها» — چون زلزله و سیل — فعال شد — انسان را به «اجتماع» کشاند — و اجتماع — به «مالکیت» — و مالکیت — به «نابرابری»؛ و این «سیر» — که روسو آن را در گفتار دوم می‌سازد — نشان می‌دهد که «تمدن» — برای روسو — نه «طبیعی» است و نه «قراردادی» — «تاریخی» است — یعنی محصول «اتفاقاتی» که می‌توانست «طور دیگر» باشد. این «تاریخی‌انگاری» — که هگل و مارکس آن را گرفتند — از میراث‌های بزرگ روسوست."]),
  ch("b-wph-11", 5, "نابرابری؛ خاستگاه مالکیت", ["مشهورترین صفحهٔ گفتار دوم — خاستگاه مالکیت است: «نخستین کسی که قطعه زمینی را حصار کشید و گفت «این مال من است» — و مردمی ساده‌دل یافت که او را باور کنند — بنیان‌گذار جامعهٔ مدنی بود». روسو — که این جمله را با «افسوس» می‌گوید — می‌خواهد بگوید: مالکیت — نه «حق طبیعی» — که «قراردادی» است — و قراردادی که «نابرابری» را بنیاد نهاد. و این نابرابری — که با مالکیت شروع شد — سه مرحله دارد: «ثروت» — که فقیر و غنی ساخت؛ «قدرت» — که قوی و ضعیف ساخت؛ و «استبداد» — که ارباب و برده ساخت؛ و در مرحلهٔ آخر — نابرابری — به «نقطهٔ آغاز» بازمی‌گردد — یعنی همه — در برابر مستبد — «برابرِ هیچ» می‌شوند. این «دیالکتیک نابرابری» — که مارکس از آن آموخت — از ماندگارترین صفحات روسوست."]),
  ch("b-wph-11", 6, "چه مشروع است؟", ["قرارداد اجتماعی — که با «انسان آزاد زاده می‌شود» آغاز شد — در فصل‌های نخست — می‌پرسد: اگر انسان «آزاد» زاده می‌شود — پس «فرمان‌بردن» — که همه‌جا هست — چگونه «مشروع» می‌شود؟ روسو — که دو پاسخ رایج را می‌سنجد — هر دو را رد می‌کند: «زور» — مشروعیت نمی‌سازد — زیرا «قوی‌ترین — همواره قوی نیست» — و اطاعت از ترس — «اطاعت» نیست — «احتیاط» است؛ و «پدرسالاری» — که فیلمر می‌گفت — نیز — چون پدری — «طبیعی» نیست و «موقت» است — پایهٔ سلطنت نمی‌شود. پس مشروعیت — نه از «زور» می‌آید و نه از «طبیعت» — از «قرارداد» می‌آید — یعنی از «توافق آزادانه»؛ و این — بنیاد کل کتاب است: قدرتِ مشروع — فقط قدرتی است که «آزادان» — با «ارادهٔ خود» — ساخته باشند."]),
  ch("b-wph-11", 7, "پیمان اجتماعی؛ صورت‌بندی", ["روسو — که می‌خواهد «قرارداد» را دقیق صورت‌بندی کند — مسئله را چنین می‌نهد: انسان‌ها — که در وضع طبیعی — به «موانعی» رسیده‌اند که به تنهایی نمی‌توانند بر آن‌ها چیره شوند — باید «اتحاد» کنند؛ اما چگونه اتحاد کنند — بی‌آنکه «آزادی» خود را از دست بدهند؟ پاسخ — «پیمان اجتماعی» است: «هر یک از ما — شخص و همهٔ قدرت خود را — به طور مشترک — تحتِ فرمانِ ارادهٔ عام قرار می‌دهیم». این جمله — که قلب کتاب است — دو نکته دارد: نخست — «سپردن» — نه به «شخصی» — که به «مشترک» است — پس هیچ‌کس — «ارباب» نمی‌شود؛ و دوم — چون «همه» می‌سپارند — و «هر کس» — جزئی از این «همه» است — پس هر کس — با سپردن به همه — در حقیقت — «به خود» سپرده است — و «آزاد» می‌ماند. این «معمای روسو» — که با آن — «فرمان‌بردن و آزاد ماندن» یکی می‌شود — کل قرارداد اجتماعی است."]),
  ch("b-wph-11", 8, "ارادهٔ عام؛ قلب قرارداد", ["«ارادهٔ عام» — که مشهورترین و مناقشه‌انگیزترین مفهوم روسوست — چنین ساخته می‌شود: وقتی همهٔ شهروندان — «به عنوان شهروند» — یعنی فارغ از «منافع خصوصی» — دربارهٔ «خیر مشترک» داوری می‌کنند — آنچه از «جمع» این داوری‌ها برمی‌خیزد — نه «مجموعهٔ خواست‌ها» — که «ارادهٔ عام» است. این اراده — برای روسو — سه ویژگی دارد: «همیشه درست است» — چون خیر مشترک را می‌جوید؛ «تقسیم‌ناپذیر» است — چون یکی است؛ و «تفویض‌ناپذیر» است — چون خود مردم — نه نمایندگان‌شان — باید آن را بخواهند. خواننده باید بداند که ارادهٔ عام — نه «نظر اکثریت» است — که «خیر مشترک» — و اکثریت — فقط «نشانه‌ای» از آن است؛ و این تمایز — که اغلب نادیده گرفته می‌شود — کلید فهم روسو است."]),
  ch("b-wph-11", 9, "ارادهٔ همه و ارادهٔ عام؛ تمایز", ["روسو — که می‌داند «ارادهٔ عام» به «نظر اکثریت» اشتباه گرفته می‌شود — تمایزی می‌سازد که کلیدی است: «ارادهٔ همه» — مجموعهٔ «خواست‌های خصوصی» است — یعنی اگر هر کس بگوید «من چه می‌خواهم» — و جمع بزنیم — ارادهٔ همه است؛ اما «ارادهٔ عام» — آنچه همه — «به عنوان شهروند» — برای «همه» می‌خواهند — است. و چون ارادهٔ همه — با «معاملات خصوصی» — فاسد می‌شود — روسو هشدار می‌دهد: در رأی‌گیری — نباید «هیچ انجمن و دسته‌ای» باشد — تا هر کس — «تنها» — با «خیر مشترک» داوری کند؛ و اگر «دسته‌ها» باشند — اراده — «عام» نمی‌شود — «دسته‌ای» می‌شود. این تمایز — که برای دموکراسی معاصر — با لابی‌ها و احزاب — از زنده‌ترین مسائل است — نشان می‌دهد روسو — دموکراسی را — نه «شمارش خواست‌ها» — که «کشف خیر مشترک» می‌دانست."]),
  ch("b-wph-11", 10, "حاکمیت؛ تفویض‌ناپذیر و تقسیم‌ناپذیر", ["روسو — که می‌خواهد «حاکمیت» را از ارادهٔ عام بسازد — دو ویژگی برای آن برمی‌شمارد: «تفویض‌ناپذیری» — یعنی مردم — نمی‌توانند حاکمیت را به «نمایندگانی» بسپارند که «به جای آنان» بخواهند — و روسو — پارلمان انگلستان را — که مردم — فقط در «لحظهٔ انتخابات» آزادند — مسخره می‌کند؛ و «تقسیم‌ناپذیری» — یعنی حاکمیت — را نمی‌توان به «قوه‌هایی» تقسیم کرد — چون اراده — یکی است. این دو ویژگی — که روسو را از لیبرالیسم جدا می‌کند — برای دموکراسی «مستقیم»‌اند نه «نیابتی»؛ و خواننده می‌بیند که روسو — با این دو ویژگی — چالشی برای همهٔ دموکراسی‌های معاصر ساخته است؛ و «رفراندوم‌ها» و «مجامع شهروندی» — پاسخ‌های امروز به این چالَش‌اند."]),
  ch("b-wph-11", 11, "قانون؛ مردم به‌مثابه قانون‌گذار", ["روسو — که می‌خواهد بگوید «قانون» چیست — تعریفی می‌سازد که از ظریف‌ترین تعاریف حقوقی است: قانون — «مصوبهٔ ارادهٔ عام» است — یعنی فرمانی که «از همه» برمی‌خیزد و «به همه» می‌پردازد — نه «از برخی» و «به برخی». پس فرمانی که به «شخص یا مورد خاص» بپردازد — قانون نیست — «فرمان» است؛ و چون قانون — «کلی» است — «عادل» نیز هست — زیرا هیچ‌کس — برای «خودِ خاص» — قانون ناعادل نمی‌سازد. این تحلیل — که قانون را «خودفرمانی» می‌داند — بنیاد «حاکمیت قانون» روسویی است؛ و خوانندهٔ حقوق — که آثار کاتوزیان را خوانده — می‌بیند که روسو — با این تعریف — «مشروعیت قانون» را — نه به «شکل» — که به «منشأ و کلیت» گره زده است."]),
  ch("b-wph-11", 12, "قانون‌گذار؛ لیکورگ و موسی", ["روسو — که می‌داند «مردم» — همیشه نمی‌دانند «خیر مشترک» چیست — شخصیتی می‌سازد که از شگفت‌انگیزترین شخصیت‌های فلسفهٔ سیاسی است: «قانون‌گذار» — کسی که «قوانین بنیادین» را می‌نویسد — اما «قدرتی» ندارد؛ «می‌بیند» — اما «حکم نمی‌کند». این قانون‌گذار — که روسو نمونه‌هایش را لیکورگ و موسی و محمد می‌داند — باید «هوشی برتر» داشته باشد — که «طبیعت انسان» را بشناسد — و «زبانی» — که مردم بفهمند — و چون مردم — «دلایل» را نمی‌فهمند — باید به «الهیات» متوسل شود — تا قانون را «مقدس» کند. این صفحه — که منتقدان روسو آن را «نقطهٔ تاریک» کتاب می‌خوانند — پرسشی را باز می‌گذارد: چگونه مردمی که «قانون‌گذار» لازم دارند — «حاکم» خود باشند؟ و این «پارادوکس تأسیس» — از زنده‌ترین مسائل فلسفهٔ سیاسی است."]),
  ch("b-wph-11", 13, "دین مدنی؛ ایمان و شهر", ["روسو — در فصل «دین مدنی» — که از بحث‌انگیزترین فصل‌های کتاب است — سه نوع دین را می‌سنجد: «دین انسان» — که مسیحیتِ انجیلی است — و چون «دل‌ها» را از «شهر» می‌گیرد — برای روسو «ناسازگار با اجتماع» است؛ «دین شهروند» — که دین رسمی شهر است — و چون «تعصب» می‌سازد — «خطرناک» است؛ و «دین مدنی» — که روسو پیشنهاد می‌کند — «اعقادی ساده» است — چون «وجود خدای توانا و مهربان» و «قدسیت قرارداد» — که «شهروند» را به «شهر» می‌بندد — و چون «تسامح» را نیز می‌آموزد — «صلح» را نگه می‌دارد. این فصل — که روسو را به «دادگاه» کشاند و کتاب را ممنوع کرد — برای خوانندهٔ مکتب‌خانه — که نسبت دین و سیاست را در سنت اسلامی می‌شناسد — گفت‌وگویی می‌سازد؛ و خواننده می‌بیند که پرسش «ایمان و شهر» — در همهٔ سنت‌ها — باز است."]),
  ch("b-wph-11", 14, "حکومت؛ مجری قانون", ["روسو — که «حاکمیت» را به مردم داد — اما می‌داند که «اجرای قانون» — را مردم نمی‌توانند — «حکومت» را می‌سازد: حکومت — «واسطه‌ای» است میان «حاکم» — که مردم‌اند — و «مردم» — که فرمان‌برند؛ و چون «واسطه» است — «نمایندهٔ حاکم» نیست — «کارگزار» اوست — و حاکم — می‌تواند او را — هر وقت که بخواهد — «عزل» کند. این تحلیل — که حکومت را «ابزار» می‌داند نه «ارباب» — از مهم‌ترین میراث‌های روسو برای فلسفهٔ سیاسی است؛ و خواننده می‌بیند که روسو — با این تحلیل — «تفکیک قوا» را — نه بین «قوه‌ها» — که بین «حاکمیت و حکومت» — یعنی بین «اراده و اجرا» — می‌نشاند؛ و این — بنیاد «نظارت مردم بر حکومت» است."]),
  ch("b-wph-11", 15, "دموکراسی؛ حکومت همه", ["روسو — که انواع حکومت را می‌سنجد — «دموکراسی» — که در آن «همه» یا «اکثریت» حکومت می‌کنند — را چنین داوری می‌کند: دموکراسی — «بهترین» حکومت است — اما برای «خدایان» — نه انسان‌ها؛ زیرا شرایطی می‌خواهد که تقریباً هیچ‌جا نیست: «شهر کوچک» — که شهروندان یکدیگر را بشناسند؛ «برابری ثروت» — که فقیر و غنیِ افراطی نباشد؛ «سادگی اخلاق» — که تظاهر و رقابت کم باشد؛ و «کم‌ترین تجمل» — که طمع نباشد. و روسو — که می‌گوید «اگر ملتی از خدایان بود — با دموکراسی حکومت می‌کرد» — عملاً — دموکراسیِ مستقیم را برای انسان‌ها «دست‌نیافتنی» می‌داند؛ و این — برای خواننده‌ای که روسو را «پدر دموکراسی» می‌خواند — تکان‌دهنده است؛ و نشان می‌دهد که روسو — دموکراتی است — با «چشمان باز»."]),
  ch("b-wph-11", 16, "آریستوکراسی؛ حکومت برگزیدگان", ["روسو — که دموکراسی را برای «خدایان» دانست — «آریستوکراسی» را — که در آن «برخی» حکومت می‌کنند — سه گونه می‌شمارد: «طبیعی» — که بر اساس سن و تجربه است — و برای «اقوام ساده» مناسب است؛ «انتخابی» — که مردم — «شایستگان» را برمی‌گزینند — و روسو آن را «بهترین» حکومت برای انسان‌ها می‌داند؛ و «ارثی» — که حکومت را «خاندانی» می‌کند — و روسو آن را «بدترین» می‌خواند. آریستوکراسی انتخابی — برای روسو — مزایایی دارد: «حکومتِ شایستگان» — که «خردمندتر» از توده‌اند؛ «جلسات آسان‌تر» — که چون کم‌شمارند — بهتر مشورت می‌کنند؛ و «اعتبار خارجی» — که چون «نظم» دارد — در خارج — «محترم» است. این تحلیل — که روسو را به «جمهوری‌خواهی منتخب» می‌رساند — نشان می‌دهد روسو — نه «دموکرات مطلق» — که «جمهوری‌خواه عمل‌گرا» است."]),
  ch("b-wph-11", 17, "سلطنت؛ حکومت یکی", ["روسو — که «سلطنت» — حکومت یکی — را می‌سنجد — می‌گوید: سلطنت — برای «دولت‌های بزرگ» مناسب است — زیرا «قدرتِ متمرکز» — در وسعت — لازم است؛ اما سلطنت — «خطرهایی» دارد که از همه بیشتر است: نخست — «جانشینی» — که با مرگ شاه — «خلاء» می‌سازد و «توطئه» می‌آورد؛ دوم — «وزیران» — که چون شاه — «همهٔ کارها» را نمی‌تواند — قدرت واقعی را می‌گیرند؛ و سوم — «فساد دربار» — که «خوشامدگویی» را جای «شایستگی» می‌نشاند. و روسو — که می‌گوید «سلطنت — همواره به استبداد می‌انجامد» — عملاً — سلطنت را «ناپایدارترین» حکومت می‌داند؛ و خواننده می‌بیند که روسو — با این تحلیل — «انقلاب» را — نه «شورش» — که «نتیجهٔ طبیعی سلطنت فاسد» می‌خواند."]),
  ch("b-wph-11", 18, "حکومت مختلط؟", ["روسو — که انواع حکومت را شمرد — می‌پرسد: آیا «حکومت مختلط» — که منتسکیو ستود — بهتر است؟ و پاسخ می‌دهد: نه — زیرا حکومت — باید «یکی» باشد — وگرنه — «اراده» — تقسیم می‌شود و «ضعیف» می‌شود؛ اما — می‌افزاید — حکومت — می‌تواند «بخش‌بخش» شود — یعنی «مجریان» — میان بخش‌ها تقسیم شوند — بی‌آنکه «حاکمیت» — که یکی است — تقسیم شود. این تمایز — میان «حاکمیت» و «مجریان» — از ظریف‌ترین حرکات روسو است؛ و نشان می‌دهد روسو — با منتسکیو — که «تفکیک قوا» را می‌خواست — موافق است — اما نه در «حاکمیت» — که در «اجرا»؛ و خواننده می‌بیند که این تمایز — که در قانون اساسی‌های معاصر — با «تفکیک قوا» و «حاکمیت مردم» — زنده است — از میراث‌های ماندگار قرارداد اجتماعی است."]),
  ch("b-wph-11", 19, "فساد حکومت؛ مرگ بدن سیاسی", ["روسو — که می‌خواهد بگوید چرا حکومت‌ها — حتی بهترین‌ها — می‌میرند — قانونی می‌سازد که از تکان‌دهنده‌ترین صفحات کتاب است: «بدن سیاسی — چون بدن انسان — از روز تولد — رو به مرگ دارد»؛ زیرا حکومت — که «مجری» است — همواره می‌کوشد «حاکمیت» را — که مال مردم است — «بگیرد»؛ و این «تمایل طبیعی حکومت» — چون «جاذبه» است — و هیچ حکومتی — از آن مصون نیست. پس مرگ بدن سیاسی — «طبیعی» است — و تنها پرسش — «چگونه دیرتر» است؛ و روسو — راه «تأخیر» را — «مجامع مردمی» می‌داند — که مردم — در آن — «حاکمیت» را — از حکومت «پس» می‌گیرند. این تحلیل — که «فروپاشی قدرت» را «طبیعی» می‌داند — برای خوانندهٔ تاریخ — که سقوط سلسله‌ها را دیده — آشناست؛ و نشان می‌دهد روسو — «تاریخ‌شناس» بود پیش از آنکه «فیلسوف» باشد."]),
  ch("b-wph-11", 20, "رأی و انجمن‌ها", ["روسو — که می‌خواهد «مجامع مردمی» را — که «حاکمیت» را نگه می‌دارند — عملی کند — به «رأی» می‌رسد: رأی — برای روسو — نه «ابراز خواست خصوصی» — که «کشف خیر مشترک» است — یعنی هر رأی‌دهنده — باید از خود بپرسد «خیر مشترک چیست؟» — نه «من چه می‌خواهم؟»؛ و اگر «اکثریت» — پاسخی داد که با «نظر من» متفاوت بود — من — نباید بگویم «شکست خوردم» — باید بگویم «اشتباه می‌کردم» — زیرا ارادهٔ عام — که اکثریت نشان می‌دهد — «همیشه درست است». این تحلیل — که رأی را «شناختی» می‌داند نه «ارادی» — از مناقشه‌انگیزترین مواضع روسوست؛ و منتقدان — از کنستانت تا برلین — آن را «ریشهٔ توتالیتاریسم» خوانده‌اند؛ و خواننده باید بداند که این صفحه — هم «قلب» دموکراسی روسویی است و هم «زخم» آن."]),
  ch("b-wph-11", 21, "دسته‌ها و احزاب؛ هشدار روسو", ["روسو — که می‌خواهد «ارادهٔ عام» را از «ارادهٔ دسته‌ها» نگه دارد — هشدار می‌دهد: اگر «دسته‌ها و احزاب» باشند — اراده — «عام» نمی‌شود — «دسته‌ای» می‌شود؛ زیرا هر کس — نه با «خیر مشترک» — که با «خواست دسته‌اش» داوری می‌کند. پس — برای روسو — در رأی‌گیری — «هیچ انجمنی» نباید باشد — و هر شهروند — باید «تنها» داوری کند. این هشدار — که برای دموکراسی معاصر — با احزاب و لابی‌ها — «غیرعملی» می‌نماید — اما پرسشی را طرح می‌کند که هنوز زنده است: آیا احزاب — «واسطهٔ مردم»‌اند یا «جایگزین مردم»؟ و خواننده می‌بیند که روسو — با این هشدار — «دموکراسی حزبی» را — که امروز رایج است — از ریشه به پرسش کشیده است؛ و این — از دلایل زنده‌بودن قرارداد اجتماعی است."]),
  ch("b-wph-11", 22, "الگوی روم؛ کومیتیا", ["روسو — که می‌خواهد «مجامع مردمی» را — با «مثال تاریخی» نشان دهد — به «رم» می‌رود: کومیتیا — که سه گونه بود — کوریاتی و سانتوریاتی و تریباتی — هر یک — «کارکردی» داشت؛ و تریبون‌ها — که «نمایندگان مردم» بودند — «واسطهٔ» میان مردم و سنا؛ و دیکتاتوری — که در «بحران» — برای «مدت کوتاه» — قدرت مطلق می‌گرفت — و سانسورها — که «اخلاق» را نگهبانی می‌کردند. روسو — که این نهادها را با «دقت» تحلیل می‌کند — می‌خواهد بگوید: رومیان — که «آزادترین» مردم بودند — نه با «دموکراسی مطلق» — که با «نهادهای متوازن» آزاد ماندند؛ و خواننده می‌بیند که روسو — که او را «رؤیاپرداز» می‌خوانند — در این فصل — «مهندس نهاد» است — و این — برای فهم کامل روسو — لازم است."]),
  ch("b-wph-11", 23, "تریبونات و دیکتاتوری؛ نهادهای بحران", ["روسو — که «تریبونات» و «دیکتاتوری» رمی را تحلیل می‌کند — دو درس می‌گیرد: تریبونات — که «نه در حاکمیت» است و «نه در حکومت» — «واسطهٔ» میان این دو است — و اگر «در حد خود» بماند — «پاسدار قانون» است — اما اگر «فراتر» رود — «مستبد» می‌شود؛ و دیکتاتوری — که برای «بحران» است — اگر «کوتاه» باشد — «نجات‌بخش» است — اما اگر «طولانی» شود — «استبداد» است. این تحلیل — که «نهادهای بحران» را می‌سنجد — برای خوانندهٔ امروز — که «حکومت‌های اضطراری» را می‌بیند — از زنده‌ترین مسائل است؛ و نشان می‌دهد روسو — می‌دانست که «بحران» — هم «فرصت» است و هم «خطر»؛ و هنر سیاست — در «مدیریت این دوگانه» است."]),
  ch("b-wph-11", 24, "سانسور؛ نگاهبان اخلاق", ["روسو — که می‌خواهد «اخلاق» را — که پایهٔ قانون است — نگه دارد — «سانسور» را می‌سازد: سانسور — برای روسو — نه «ممنوعیت کتاب» — که «نگهبانی از افکار عمومی» است — یعنی «اعلام» آنچه «افکار عمومی» — که «قانونِ نانوشته» است — «درست» می‌داند. و چون افکار عمومی — «پادشاه» اخلاق است — سانسور — اگر «درست» عمل کند — اخلاق را «پاک» نگه می‌دارد — و اگر «فاسد» شود — اخلاق را «نابود» می‌کند. این فصل — که برای خوانندهٔ معاصر — با واژهٔ «سانسور» — ناخوشایند است — باید با دقت خوانده شود؛ زیرا روسو — در حقیقت — دربارهٔ «نقش افکار عمومی» سخن می‌گوید — و پرسشش — که هنوز زنده است — این است: چگونه می‌توان «افکار عمومی» را — که «قانون نانوشته» است — از «فساد» نگه داشت؟"]),
  ch("b-wph-11", 25, "آزادی؛ فرمان‌بردن از قانون خود", ["روسو — که می‌خواهد بگوید «آزادی» — در قرارداد — چیست — پاسخ می‌دهد: آزادی — نه «کردن هر چه می‌خواهی» — که «فرمان‌بردن از قانونی است که خود ساخته‌ای». این تعریف — که «آزادی مثبت» خوانده شد — از مهم‌ترین مفاهیم فلسفهٔ سیاسی است: انسان طبیعی — «آزادی طبیعی» داشت — که بی‌حد بود؛ انسان مدنی — «آزادی مدنی» پیدا می‌کند — که «محدود به قانون» است — اما چون قانون — «خودساخته» است — این محدودیت — «اسارت» نیست — «خودفرمانی» است. و روسو — جمله‌ای مشهور می‌گوید: «هر کس — از فرمان‌بردن از ارادهٔ عام سرپیچی کند — جامعه — او را «مجبور به آزاد بودن» می‌کند». این جمله — که از مناقشه‌انگیزترین جملات تاریخ سیاست است — هم «قلب» آزادی روسویی است و هم «زخم» آن؛ و خواننده باید هر دو را ببیند."]),
  ch("b-wph-11", 26, "روسو و هابز؛ دو قرارداد", ["روسو — که قرارداد اجتماعی را نوشت — با هابز — که لویاتان را نوشت — در «گفت‌وگو» است: هر دو — از «وضع طبیعی» آغاز می‌کنند و به «قرارداد» می‌رسند؛ اما تفاوت‌ها — بنیادین‌اند: هابز — وضع طبیعی را «جنگ» می‌داند — روسو «آرامش»؛ هابز — قرارداد را «سپردن همهٔ حقوق به یکی» می‌داند — روسو «سپردن به همه»؛ هابز — حاکم را «فراتر از قرارداد» می‌داند — روسو حاکمیت را «خودِ مردم»؛ و هابز — آزادی را «سکوت قانون» می‌داند — روسو «فرمان‌بردن از قانون خود». این چهار تفاوت — دو جهان می‌سازد: جهان هابز — که «امنیت» را بر «آزادی» مقدم می‌دارد — و جهان روسو — که «آزادی» را بر «امنیت». خواننده — که هر دو را خوانده — می‌بیند که تاریخ سیاست معاصر — تا حد زیادی — گفت‌وگوی این دو جهان است."]),
  ch("b-wph-11", 27, "روسو و لاک؛ مالکیت و حاکمیت", ["روسو — با لاک نیز — در گفت‌وگوست: هر دو — «قرارداد» را بنیاد مشروعیت می‌دانند؛ اما لاک — مالکیت را «پیش از قرارداد» می‌داند — و قرارداد — برای «حفظ مالکیت» است؛ روسو — مالکیت را «ساختهٔ قرارداد» می‌داند — و قرارداد — می‌تواند «محدودش» کند. و لاک — حاکمیت را «مشروط به حفظ حقوق» می‌داند — و اگر حاکم تجاوز کند — مردم حق «انقلاب» دارند؛ روسو — حاکمیت را «خودِ مردم» می‌داند — پس «انقلاب» — معنایی ندارد — زیرا مردم — نمی‌توانند بر «خود» بشورند. این تفاوت‌ها — که ظاهراً فنی‌اند — دو «لیبرالیسم» می‌سازند: لیبرالیسم لاک — که «حقوق» را بر «دموکراسی» مقدم می‌دارد — و لیبرالیسم روسویی — که «دموکراسی» را بر «حقوق»؛ و خواننده می‌بیند که مناقشهٔ «لیبرالیسم و دموکراسی» — که امروز زنده است — ریشه در این گفت‌وگوی قرن هجدهمی دارد."]),
  ch("b-wph-11", 28, "روسو و منتسکیو؛ قانون و اقلیم", ["روسو — با منتسکیو — که «روح قوانین» را نوشت — نیز در گفت‌وگوست: منتسکیو — می‌گوید قانون — باید با «اقلیم و خاک و خلق‌وخوی مردم» سازگار باشد — و روسو — در فصل‌های «دربارهٔ قانون‌گذار» و «انواع حکومت» — همین را می‌پذیرد: قانون — برای هر مردمی — باید «متناسب» باشد — و قانونی که برای یک مردم «نیک» است — ممکن است برای مردمی دیگر «بد» باشد. اما تفاوت — در «روش» است: منتسکیو — قانون را «کشف» می‌کند — یعنی می‌بیند که قوانین «چگونه‌اند» — و روسو — قانون را «می‌سازد» — یعنی می‌پرسد که قوانین «چگونه باید باشند». این تفاوت — که منتسکیو را «جامعه‌شناس» و روسو را «فیلسوف» می‌سازد — نشان می‌دهد که قرارداد اجتماعی — با روح قوانین — «مکمل» است نه «رقیب»؛ و خواننده — که هر دو را بخواند — «دو بال» فلسفهٔ سیاسی را دارد."]),
  ch("b-wph-11", 29, "امیل؛ تربیت برای آزادی", ["«امیل» — که روسو در همان سال قرارداد اجتماعی — ۱۷۶۲ — نوشت — «مکمل» آن است: اگر قرارداد اجتماعی — می‌گوید چگونه «شهروند» بسازیم — امیل — می‌گوید چگونه «انسان» بسازیم؛ و چون «انسانِ آزاد» — پیش‌شرط «شهروند آزاد» است — امیل — «تربیت» را می‌سازد که روسو آن را «منفی» می‌خواند: یعنی — پیش از دوازده‌سالگی — «هیچ چیزی به کودک نیاموز» — فقط «بگذار طبیعتش رشد کند» — و از «شر اجتماع» نگهش دار؛ و پس از آن — با «تجربه» — نه «کتاب» — بیاموز. این «تربیت منفی» — که برای زمانه‌اش تکان‌دهنده بود — بر پداگوژی بعدی — از پستالوتسی تا مونته‌سوری و پیاژه — اثر عمیق گذاشت؛ و خوانندهٔ علوم تربیتی — که آثار کاردان و باقری را خوانده — می‌بیند که پرسش «طبیعت و تربیت» — از امیل تا امروز — باز است."]),
  ch("b-wph-11", 30, "مربی و تربیت منفی", ["امیل — که «مربی» دارد — اما مربی — برای روسو — «فرمان» نمی‌دهد — «زمینه» می‌سازد: مربی — چنان «زمینه» را می‌آراید که امیل — «خود» — به نتیجه برسد — و «پندارد» که «خود» کشف کرده است؛ و این — «هنر مربی» است. این روش — که روسو آن را «هدایت غیرمستقیم» می‌خواند — بر پایهٔ «آزادی» است: تربیت — اگر «فرمان» باشد — «برده» می‌سازد؛ و اگر «زمینه» باشد — «انسان آزاد». اما این روش — که زیباست — «پرسشی» نیز می‌سازد: آیا این «زمینه‌سازی» — که مربی — «همه‌چیزش» را کنترل می‌کند — خودش — نوعی «فرمانِ پنهان» نیست؟ و این پرسش — که منتقدان روسو — از جمله فمینیست‌ها — طرح کرده‌اند — نشان می‌دهد که امیل — چون قرارداد — هم «الهام‌بخش» است و هم «مسئله‌ساز»."]),
  ch("b-wph-11", 31, "اعتراف کشیش ساوایی؛ دین روسو", ["امیل — در کتاب چهارم — «اعتراف ایمان کشیش ساوایی» را دارد — که «مانیفست دینی» روسو است: کشیش — که از «شک» به «ایمان» رسیده — می‌گوید: من — خدا را — نه با «برهان» — که با «قلب» می‌شناسم — «وجدان» — که «غریزهٔ الهی» است — به من می‌گوید خدا هست و نیک است؛ و دین — نه «مراسم» — که «پرستش قلبی» است. این اعتراف — که کلیسا را خشمگین کرد و کتاب را — در پاریس و ژنو — سوزاند — برای روسو — «ایمان طبیعی» است — ایمانی که «بی‌کلیسا» و «بی‌وحی رسمی» — «طبیعت» و «وجدان» را می‌خواند. خوانندهٔ مکتب‌خانه — که کلام خوانده — می‌بیند که این «دین طبیعی» — که در روشنگری رایج بود — با «دین وحیانی» — در گفت‌وگو و گاه در ستیز است؛ و خواندن اعتراف کشیش — برای فهم «دین در روشنگری» — لازم است."]),
  ch("b-wph-11", 32, "ژولی؛ احساس و اجتماع", ["«ژولی یا هلوئیز نو» — رمان نامه‌نگار روسو — که در ۱۷۶۱ منتشر شد و از پرفروش‌ترین کتاب‌های قرن هجدهم بود — «بعد احساسی» فلسفهٔ روسوست: داستان عشق «سن‌پره» — مربی — و «ژولی» — شاگرد — که به «ازدواج ناموفق» می‌انجامد — و روسو — در آن — می‌خواهد بگوید: «احساس» — که تمدن آن را «فاسد» کرده — می‌تواند با «فضیلت» — «بازگردد»؛ و این بازگشت — نه با «سرکوب احساس» — که با «جهت‌دادن به آن» است. این رمان — که گوته و تولستوی را تحت تأثیر قرار داد — نشان می‌دهد روسو — نه فقط «فیلسوف قرارداد» — که «شاعر احساس» نیز بود؛ و خواننده می‌بیند که فلسفهٔ روسو — بی‌بعد احساسی‌اش — «نیمه» است؛ و این — راز تأثیر او بر «رومانتیسیسم» است."]),
  ch("b-wph-11", 33, "اعترافات؛ شفافیت", ["«اعترافات» روسو — که پس از مرگش — ۱۷۸۲ — منتشر شد — «خودنوشتی» است که با جمله‌ای آغاز می‌شود که از شجاع‌ترین جملات ادبیات است: «می‌خواهم به همنوعانم انسانی را — در تمام حقیقت طبیعت — نشان دهم — و این انسان — خودم خواهم بود». روسو — در اعترافات — «همه‌چیز» را می‌گوید — از «دزدی‌های کودکی» تا «رابطه‌هایش» — و هدفش — «شفافیت» است: انسانی که «هیچ‌چیز را پنهان نمی‌کند» — آیا می‌تواند «محکوم» شود؟ این «خودنماییِ بی‌پرده» — که آگوستین — در اعترافاتش — برای «خدا» کرد — روسو — برای «مردم» کرد؛ و این — آغاز «خودنوشتی مدرن» است. خوانندهٔ ادبیات — که مونتنی را خوانده — می‌بیند که اعترافات روسو — «مرحلهٔ بعد» خودنوشتی است؛ و روانکاوی — چهار قرن بعد — این «شفافیت» را «روش درمان» ساخت."]),
  ch("b-wph-11", 34, "خیال‌پردازی‌ها؛ تنهایی", ["«خیال‌پردازی‌های یک تنها‌روی» — که روسو در سال‌های آخر — ۱۷۷۶ تا ۱۷۷۸ — نوشت — «وصیت‌نامهٔ روح» اوست: روسو — که از همه «رانده» شده بود — و می‌پنداشت همه «توطئه» علیه او کرده‌اند — به «تنهایی» پناه برد — و در «پیاده‌روی‌هایش» — این خیال‌پردازی‌ها را نوشت: دربارهٔ «گیاه‌شناسی» — که می‌گفت «تنها علم بی‌ضرر» است؛ دربارهٔ «خاطرات» — که می‌خواست «خود» را — برای «خود» — بازگوید؛ و دربارهٔ «لحظهٔ حال» — که می‌گفت «تنها حقیقت» است. این کتاب — که از زیباترین صفحات ادبیات فرانسه است — روسو را — نه «فیلسوف اجتماع» — که «شاعر تنهایی» می‌سازد؛ و خواننده می‌بیند که روسو — که «ارادهٔ عام» را ساخت — خود — در «تنهایی مطلق» مرد؛ و این تناقض — خود — از موضوعات جالب روان‌شناسی خلاقیت است."]),
  ch("b-wph-11", 35, "انقلاب فرانسه؛ وارثان ناخواسته", ["قرارداد اجتماعی — که در ۱۷۶۲ ممنوع شد — بیست‌وهفت سال بعد — «کتاب مقدس انقلاب فرانسه» بود: روبسپیر — که آن را «چهل بار» خوانده بود — «ارادهٔ عام» را شعار انقلاب کرد؛ و «اعلامیهٔ حقوق بشر» — ۱۷۸۹ — ردپای روسو را دارد — با تأکیدش بر «حاکمیت مردم» و «قانون — بیان ارادهٔ عام». اما انقلاب — که «ترور» نیز ساخت — پرسشی را باز کرد: آیا «ترور» — نتیجهٔ «ارادهٔ عام» بود؟ مدافعان روسو می‌گویند نه — انقلاب — «خیانت» به روسو بود؛ و منتقدان می‌گویند آری — «ارادهٔ عامِ مطلق» — به «ترور» می‌انجامد. خواننده باید بداند که این بحث — که «مسئولیت متفکر» را طرح می‌کند — هنوز باز است؛ و قرارداد اجتماعی — چون همهٔ متون بزرگ — «ظرف تفسیرهای متعارض» است."]),
  ch("b-wph-11", 36, "کنستانت؛ آزادی باستانیان", ["بنژامن کنستانت — که در ۱۸۱۹ — سخنرانی مشهورش را دربارهٔ «آزادی باستانیان و مدرنان» ایراد کرد — مستقیم‌ترین نقد لیبرالی بر روسو است: آزادی باستانیان — که روسو آن را می‌خواست — «مشارکت مستقیم در حاکمیت» بود — و چون «زندگی خصوصی» نداشت — «فرد» را می‌بلعید؛ و آزادی مدرنان — «استقلال خصوصی» است — و چون «مشارکت مستقیم» ندارد — «شهروند» را کم‌رنگ می‌کند. کنستانت — که می‌خواست هر دو را نگه دارد — گفت: روسو — «آزادی باستانیان» را — در «جامعهٔ مدرن» — خواست — و این — به «استبداد» انجامید؛ و خواننده می‌بیند که نقد کنستانت — که «اندازهٔ جامعه» را به مسئله افزود — از ماندگارترین نقدهای روسوست؛ زیرا نشان می‌دهد که «الگوهای سیاسی» — «متناسب با مقیاس»‌اند."]),
  ch("b-wph-11", 37, "هگل؛ ارادهٔ عام و دولت", ["هگل — که روسو را «کسی که اراده را اصل دولت کرد» می‌ستود — اما نقدی اساسی بر او دارد: «ارادهٔ عام» روسو — «انتزاعی» است — یعنی از «افراد جدا» برمی‌خیزد — و به «دولت» نمی‌رسد؛ و دولت — برای هگل — نه «قرارداد افراد» — که «روح عینی» است — یعنی «سنت و نهادی» که افراد را «پیش از قرارداد» می‌سازد. پس نقد هگل — این است که روسو — «اجتماع را از فرد می‌سازد» — در حالی که «فرد — از اجتماع ساخته می‌شود»؛ و این نقد — که «جوامع‌گرایی» بعدی — از مک‌اینتایر تا سندل — آن را ادامه داد — از مهم‌ترین نقدهای فلسفی بر روسو است. خواننده — که جوامع‌گرایی را در درس فلسفهٔ سیاسی خوانده — می‌بیند که این مناقشه — که در قرن نوزدهم آغاز شد — هنوز — «محور» بحث‌های لیبرالیسم و جوامع‌گرایی است."]),
  ch("b-wph-11", 38, "کانت؛ خودمختاری", ["کانت — که گفت «روسو — نیوتنِ جهان اخلاقی است» — از او «خودمختاری» را گرفت: اخلاق — برای کانت — «فرمان‌بردن از قانونی است که خود — به عنوان موجود عقلانی — ساخته‌ای»؛ و این — دقیقاً — همان ساختار «فرمان‌بردن از قانون خود» روسوست — اما کانت — آن را از «ارادهٔ عامِ شهروندان» به «عقلِ همهٔ موجودات عقلانی» برد. پس کانت — که «ارادهٔ عام» روسو را «عقلانی» کرد — روسو را از «شهر» به «جهان» برد؛ و این — معنای «عمومیت‌بخشی» کانتی است: قانونی که «همهٔ موجودات عقلانی» بپذیرند — نه فقط «همهٔ شهروندان». خواننده — که تأملات و نقد را خوانده — می‌بیند که کانت — با روسو — «هم‌سخن» است — و این «هم‌سخنی» — که اغلب نادیده گرفته می‌شود — از پل‌های مهم میان فلسفهٔ سیاسی و اخلاق است."]),
  ch("b-wph-11", 39, "برلین؛ دو مفهوم آزادی", ["آیزایا برلین — که در ۱۹۵۸ — «دو مفهوم آزادی» را ایراد کرد — روسو را — با هابز و هگل — در «آزادی مثبت» نشاند: آزادی مثبت — که «خودفرمانی» است — می‌پرسد «چه کسی بر من فرمان می‌راند؟» — و پاسخ روسو — «خودم — به عنوان ارادهٔ عام» — است؛ اما برلین هشدار می‌دهد: این «خودِ واقعی» — که روسو می‌سازد — می‌تواند به «بهانه» بدل شود: «من — بهتر از تو — می‌دانم که «خود واقعی‌ات» چه می‌خواهد» — و این — راه «استبدادِ به نام آزادی» است. این نقد — که از مشهورترین نقدهای لیبرالی بر روسوست — اما پاسخ‌هایی نیز دارد: مدافعان روسو می‌گویند «ارادهٔ عام» — نه «خودِ واقعیِ پنهان» — که «خیر مشترکِ کشف‌شده با مشارکت» است؛ و خواننده می‌بیند که این بحث — که «مرز آزادی و استبداد» را طرح می‌کند — از زنده‌ترین بحث‌های فلسفهٔ سیاسی است."]),
  ch("b-wph-11", 40, "توکویل؛ دموکراسی و همسان‌سازی", ["توکویل — که «دموکراسی در آمریکا» را نوشت — با روسو — در «گفت‌وگوی پنهان» است: هر دو — «برابری» را «روند اجتناب‌ناپذیر» می‌دانند؛ اما توکویل — می‌پرسد: آیا «برابری» — با «آزادی» می‌سازد؟ و پاسخش — «مشروط» است: برابری — اگر با «نهادهای میانی» — چون انجمن‌ها و شهرداری‌ها — همراه باشد — آزادی را «تقویت» می‌کند؛ و اگر «بی‌نهاد» باشد — به «همسان‌سازی» و «استبداد نرم» می‌انجامد. این تحلیل — که توکویل را «روسوی تعدیل‌شده» می‌سازد — نشان می‌دهد که پرسش روسو — «چگونه در اجتماعِ برابر — آزاد بمانیم؟» — برای توکویل نیز — «پرسش اصلی» بود؛ و خواننده می‌بیند که این پرسش — که در قرن نوزدهم طرح شد — در قرن بیست‌ویکم — با شبکه‌های اجتماعی و همسان‌سازی — زنده‌تر از همیشه است."]),
  ch("b-wph-11", 41, "دموکراسی مشارکتی؛ بازگشت روسو", ["دموکراسی مشارکتی — که در دهه‌های ۱۹۶۰ و ۱۹۷۰ — با کارول پتیمن و دیگران — زنده شد — مستقیم‌ترین بازگشت به روسوست: این جریان — می‌گوید دموکراسی نیابتی — که شهروندان را به «رأی‌دهندگان دوره‌ای» تقلیل می‌دهد — «نیمه‌دموکراسی» است؛ و راه نجات — «مشارکت مستقیم» است — در کارگاه‌ها و شهرداری‌ها و مجامع. پتیمن — در «مشارکت و دموکراسی» — روسو را «نظریه‌پرداز مشارکت» خواند؛ و «مجامع شهروندی» — که امروز در ایرلند و فرانسه برای مسائل مهم تشکیل می‌شوند — بازتاب «ارادهٔ عام» روسویی‌اند — البته با «تعدیل‌های لیبرالی». خواننده می‌بیند که روسو — که قرن‌ها «رؤیاپرداز» خوانده می‌شد — امروز — «الهام‌بخش عملی» است؛ و این — معنای «کلاسیک بودن» است."]),
  ch("b-wph-11", 42, "دموکراسی مشورتی؛ روسو و هابرماس", ["دموکراسی مشورتی — که هابرماس و راولز آن را ساختند — با روسو — «هم‌ریشه» است: هر دو — می‌گویند تصمیم مشروع — از «گفت‌وگو» برمی‌خیزد نه از «شمارش»؛ و هر دو — «دلایل» را — نه «خواست‌ها» — معیار مشروعیت می‌دانند. اما تفاوت — بنیادین است: هابرماس — گفت‌وگو را «بی‌پایان» می‌داند — و نتیجه‌اش — «توافقی» است که ممکن است نرسد؛ روسو — گفت‌وگو را «به نتیجه» می‌رساند — و نتیجه‌اش — «ارادهٔ عام» است — که «همیشه درست» است. این تفاوت — که «خوش‌بینی روسویی» در برابر «احتیاط هابرماسی» است — از مهم‌ترین بحث‌های دموکراسی معاصر است؛ و خواننده — که هابرماس را در درس جامعه‌شناسی خوانده — می‌بیند که این دو — با همهٔ تفاوت — «یک پرسش» دارند: چگونه تصمیم‌های جمعی — «عقلانی» و «مشروع» شوند؟"]),
  ch("b-wph-11", 43, "نقد فمینیستی؛ حوزهٔ عمومی و خصوصی", ["فمینیست‌ها — از والستون‌کرافت — که در ۱۷۹۲ «دفاع از حقوق زنان» را نوشت و روسو را نقد کرد — تا فمینیست‌های معاصر — با روسو — رابطه‌ای دوگانه دارند: از یک سو — روسو — در قرارداد — «زنان» را «شهروند» خواند — و در امیل — «تربیت دختران» را جدی گرفت؛ و از سوی دیگر — در امیل — «سوفی» — همسر امیل — را برای «خدمت به امیل» تربیت کرد — و این — با «برابری شهروندی» قرارداد — ناسازگار است. والستون‌کرافت — که این ناسازگاری را دید — گفت: اگر زنان — «عقل» دارند — پس «شهروند»‌اند — و تربیت «خدمتگزارانه» سوفی — «خیانت به اصول روسو» است. این نقد — که «نقد از درون» است — از ماندگارترین نقدهای فمینیستی است؛ و خواننده می‌بیند که سنت — حتی سنت برابری‌خواه — از نقد فمینیستی — بی‌نیاز نیست."]),
  ch("b-wph-11", 44, "تالمون؛ دموکراسی توتالیتر", ["جیکوب تالمون — که در ۱۹۵۲ — «خاستگاه‌های دموکراسی توتالیتر» را نوشت — روسو را — با بابوف و مارکس — در «توتالیتاریسم» نشاند: تالمون — می‌گوید «ارادهٔ عام» — که «همیشه درست» و «تقسیم‌ناپذیر» است — به «حزب واحد» و «حقیقت واحد» می‌انجامد؛ و «مجبور کردن به آزاد بودن» — «توجیه ترور» است. این نقد — که در اوج جنگ سرد نوشته شد — از مشهورترین نقدهای روسوست؛ اما پاسخ‌های فراوانی نیز دارد: مدافعان روسو — چون دنت — می‌گویند تالمون — «ارادهٔ عام» را — از «شرایطش» — شهر کوچک و برابری و مشارکت — جدا کرد — و این جداسازی — «خیانت به روسو» است. خواننده باید بداند که این بحث — که «مسئولیت ایده‌ها» را طرح می‌کند — هنوز باز است؛ و قرارداد اجتماعی — چون همهٔ متون بزرگ — «ظرف تفسیرهای متعارض» است."]),
  ch("b-wph-11", 45, "مدافعان روسو؛ دنت و دیگران", ["در برابر تالمون — مدافعان روسو — چون نیکلاس دنت — در «روسو» — می‌گویند: روسو — نه «توتالیتر» — که «جمهوری‌خواه» است؛ و «ارادهٔ عام» او — «استبدادی» نیست — زیرا «شرایطی» دارد که استبداد را «ناممکن» می‌کند: شهر کوچک — که «نظارت متقابل» ممکن است؛ برابری — که «سلطه» را برمی‌دارد؛ و مشارکت — که «شهروندان» را «بیدار» نگه می‌دارد. دنت — می‌گوید: اگر این شرایط را — که روسو «صریحاً» گفته — جدی بگیریم — روسو — از «لیبرال‌ترین» فیلسوفان است — زیرا هدفش — «آزادیِ واقعی» است نه «آزادیِ صوری». این دفاع — که روسو را «در شرایطش» می‌خواند — از مهم‌ترین خوانش‌های معاصر است؛ و به خواننده می‌آموزد که متون را — نه «جمله‌جمله» — که «در نظامشان» بخواند."]),
  ch("b-wph-11", 46, "روسو و بوم‌شناسی؛ طبیعت و تمدن", ["روسو — که «طبیعت» را معیار «فساد تمدن» گرفت — امروز — با «بوم‌شناسی سیاسی» — از نو خوانده می‌شود: نقد روسو بر «پیشرفت» — که می‌گفت «علوم و هنرها — اخلاق را فاسد کرده‌اند» — امروز — با «بحران اقلیمی» — رنگ تازه‌ای گرفته است؛ و پرسش روسو — «آیا پیشرفت — به بهای طبیعت و انسان — پیشرفت است؟» — پرسشِ بوم‌شناسان معاصر است. البته — باید احتیاط کرد: روسو — «ضدعلم» نبود — «ضدعلمِ بی‌اخلاق» بود؛ و «طبیعت» او — نه «جنگل» — که «طبیعت انسان» بود؛ اما این فاصله — مانع نمی‌شود که روسو — در «نقد تمدن» — «هم‌سخن» بوم‌شناسان باشد. خواننده می‌بیند که قرارداد اجتماعی — با سه قرن فاصله — برای «مسائل نوظهور» نیز — «آینه» است."]),
  ch("b-wph-11", 47, "روسو در ایران؛ ترجمه و reception", ["قرارداد اجتماعی — که با ترجمهٔ منوچهر کی‌مرام و دیگران به فارسی آمد — برای خوانندهٔ ایرانی — دو گفت‌وگوی ویژه می‌سازد: نخست — با «مشروطه» — که روشنفکرانش — با «ارادهٔ ملت» و «قانون» — هم‌سخن روسو بودند — و تنبیه الامة نائینی — که «مشروطه را از فقه» ساخت — با قرارداد اجتماعی — «گفت‌وگوی پنهان» دارد؛ و دوم — با «مسئلهٔ دولت در ایران» — که روسو — با پرسشش دربارهٔ «مشروعیت» — برای جامعه‌ای که با این مسئله روبه‌روست — «آینه» است. این گفت‌وگوها — که نباید به پذیرش یا ردّ بینجامند — از آموزنده‌ترین تمرین‌های فلسفهٔ تطبیقی‌اند؛ و خواننده می‌بیند که روسو — با همهٔ فاصلهٔ فرهنگی — «پرسش‌هایی» دارد که «جهان‌شمول»‌اند."]),
  ch("b-wph-11", 48, "روش خواندن قرارداد", ["برای خواندن قرارداد اجتماعی — که کتاب کوتاهی است — اما «متراکم» — این روش پیشنهاد می‌شود: نخست — کتاب اول را — که «بنیادها» است — با دقت بخوانید و «تعریف‌ها» را بنویسید — ارادهٔ عام، حاکمیت، قانون؛ دوم — کتاب دوم را — که «ارادهٔ عام و قانون» است — با «پرسش تطبیقی» بخوانید؛ سوم — کتاب سوم را — که «حکومت» است — با «مثال‌های تاریخی» — که روسو می‌آورد — بخوانید؛ و چهارم — کتاب چهارم را — که «نهادهای رومی» است — با «چشم تاریخ‌شناس» بخوانید. و مهم‌تر از همه — قرارداد را — «تنها» نخوانید — با «گفتارها» و «امیل» بخوانید؛ زیرا این سه — «مثلث روسویی»‌اند — و خواندن یکی — بدون دو تای دیگر — «نیمه» است. با این روش — قرارداد — از «کتابی کوتاه» — به «جهانی» بدل می‌شود."]),
  ch("b-wph-11", 49, "جمع‌بندی؛ روسو و پرسش آزادی", ["پنجاه فصل این سیر — از وضع طبیعی تا خیال‌پردازی‌ها — روسو را پیمود؛ و اکنون خواننده می‌داند که قرارداد اجتماعی — با همهٔ ابهام‌هایش — یک «پرسش» دارد: چگونه — در اجتماع — آزاد بمانیم؟ و پاسخ روسو — که «فرمان‌بردن از قانون خود» است — با همهٔ خطرهایی که دارد — «پرسشی» را زنده نگه داشت که لیبرالیسم — با «آزادی منفی»‌اش — گاه فراموش می‌کند: آزادی — نه فقط «نبودن موانع» — که «بودنِ خویشتن» است. میراث روسو — که انقلاب و رمانتیسیسم و دموکراسی مشارکتی — هر یک — از او برخاستند — نشان می‌دهد که «اندیشهٔ زنده» — ظرف تفسیرهای متعارض است؛ و خواننده‌ای که قرارداد را خوانده — دیگر نمی‌تواند «دموکراسی» را — «شمارش آرا» بداند — بی‌آنکه «خیر مشترک» را بپرسد؛ و این — آغاز «سیاست روسویی» است.", ["پروژه‌های پیشنهادی", "برای مقطع پژوهشی، چند پروژه پیشنهاد می‌شود: «ارادهٔ عام و نظارت استصوابی؛ خوانش روسویی از نهادهای مشروطه»؛ «آزادی مثبت روسو و آزادی منفی برلین؛ دو مفهوم آزادی در ایران معاصر»؛ «تربیت منفی امیل و پداگوژی‌های نو»؛ و «روسو و نائینی؛ دو دفاع از حاکمیت مردم». هر یک از این پروژه‌ها — اگر با خوانش مستقیم قرارداد و روش تطبیقی انجام شود — می‌تواند خواننده را از خوانندهٔ روسو — به گفت‌وگوکننده با روسو برساند؛ و این — همان مرتبه‌ای است که مکتب‌خانه — در همهٔ سیرهایش — خواننده را بدان می‌خواند."]]),
];

